$string['settings:embed_apibaseurl'] = 'Base URL ng Embedding API';
$string['settings:embed_apibaseurl_desc'] = 'Base URL para sa embedding API. Mag-iwan ng blangko para sa default ng OpenAI. Para sa Ollama: http://localhost:11434/api';
$string['settings:embed_apikey'] = 'API Key ng Embedding';
$string['settings:embed_apikey_desc'] = 'API key para sa embedding provider. Maaaring iba ito sa API key ng chat. Hindi kailangan para sa Ollama.';
$string['settings:embed_dimensions'] = 'Mga Dimensyon ng Embedding';
$string['settings:embed_dimensions_desc'] = 'Lapad ng embedding vector, na dapat isang lapad na talagang inaalok ng modelo. OpenAI text-embedding-3-small: 1536. nomic-embed-text: 768. Tinatanggap ng mga Voyage model ang 256, 512, 1024 at 2048 (ang native na 1024 ay tinatanggal sa request); ang di-wastong lapad ay tinatanggal kaysa ipadala, kaya tahimik na makukuha mo ang native na lapad sa halip na ang hiniling mo. Ang voyage-4-large sa 2048 ang nasukat na configuration — +14.0 percentage points na recall sa realistikong mga query, mas mababa sa $4 kada buwan — at ang paggamit nito ay nangangailangan ng BUONG RE-INDEX, dahil tinatanggihan ng retriever na i-score ang isang query laban sa mga chunk mula sa ibang embedding space. Gamitin ang embedding-model migration sa pahina ng RAG index sa halip na baguhin muna ang halagang ito.';
$string['settings:embed_model'] = 'Modelo ng Embedding';
$string['settings:embed_model_desc'] = 'Modelong gagamitin para sa paggawa ng mga embedding. Default ng OpenAI: text-embedding-3-small. Halimbawa sa Ollama: nomic-embed-text.';
$string['settings:embed_provider'] = 'Embedding Provider';
$string['settings:embed_provider_desc'] = 'The API provider used to generate text embeddings for RAG indexing and retrieval.';
