$string['settings:quiz_hide_heading'] = 'Pagpapakita sa Pahina ng Quiz';
$string['settings:quiz_hide_heading_desc'] = 'Control whether the [[tutorshort]] widget appears on Moodle quiz pages. This is stricter than the built-in summative quiz lock, which only disables chat during graded quizzes. These settings completely hide the widget on all quiz pages.';
$string['settings:rag_chunksize'] = 'Laki ng Chunk (mga salita)';
$string['settings:rag_chunksize_desc'] = 'Target na bilang ng mga salita kada chunk ng nilalaman kapag ini-index ang materyal ng kurso. Mas tumpak ang mas maliliit na chunk; mas maraming konteksto ang ibinibigay ng mas malalaking chunk.';
$string['settings:rag_return_scope'] = 'Saklaw ng ibinabalik na resulta ng pagkuha';
$string['settings:rag_return_scope_desc'] = 'Ang isasama para sa bawat nakuhang tugma. Ang "chunk" (default) ay nagsasama ng tumugmang bahagi na humigit-kumulang 400 salita. Ang "window" ay nagsasama ng tumugmang bahagi kasama ang mga kalapit na bahagi mula sa parehong pahina. Ang "page" ay nagsasama ng buong pahina ng module kung saan nabibilang ang tugma. Nakakatulong ang window/page kapag ang sagot ay sumasaklaw sa buong pahina, sa kapalit ng mas malaking prompt.';
$string['settings:rag_window_size'] = 'Laki ng window ng pagkuha';
$string['settings:rag_window_size_desc'] = 'Para sa saklaw na "window": bilang ng mga kalapit na bahagi na isasama sa bawat gilid ng isang tumugmang bahagi. Default na 1.';
$string['settings:rag_parent_max_chars'] = 'Limitasyon ng pangunahing sipi (mga karakter)';
$string['settings:rag_parent_max_chars_desc'] = 'Pinakamataas na bilang ng mga karakter para sa isang pinalawak na window/page na sipi. Ang mga pahinang lumampas sa limitasyon ay babalik sa isang window, pagkatapos ay sa iisang chunk. Default na 6000.';
$string['settings:rag_enabled'] = 'I-enable ang RAG (Semantic Search)';
$string['settings:rag_enabled_desc'] = 'Kapag naka-enable, gumagamit ang AI tutor ng semantic search para kunin ang kaugnay na nilalaman ng kurso para sa bawat query sa halip na isiksik ang lahat ng nilalaman sa system prompt.';
$string['settings:rag_heading'] = 'RAG / Semantic Search';
$string['settings:rag_heading_desc'] = 'Retrieval-Augmented Generation: i-index ang nilalaman ng kurso bilang mga embedding at kunin lamang ang pinakakaugnay na mga chunk sa oras ng query. Binabawasan nito ang paggamit ng token at sinusuportahan ang lahat ng uri ng nilalaman. Nangangailangan ng embedding API.';
$string['settings:rag_topk'] = 'Top-K na Chunk';
$string['settings:rag_topk_desc'] = 'Number of most relevant chunks to retrieve per user query and inject into the system prompt.';
$string['settings:realtime_apikey'] = 'OpenAI API Key (Boses at TTS)';
$string['settings:realtime_apikey_desc'] = 'Ginagamit para sa Voice Mode at para sa TTS speak button sa mga mensahe. Iwanang blangko upang bumalik sa pangunahing API key kapag nakatakda sa OpenAI ang provider.';
$string['settings:realtime_enabled'] = 'I-enable ang Voice Mode';
$string['settings:realtime_enabled_desc'] = 'Allows students to have real-time voice conversations with [[tutorshort]]. Requires an OpenAI API key.';
$string['settings:realtime_heading'] = 'Voice Mode (OpenAI Realtime)';
$string['settings:realtime_voice'] = '[[tutorshort]] Voice';
