$string['settings:avatar_rate_card_overrides'] = 'Mga override sa rate card ng avatar (JSON)';
$string['settings:avatar_rate_card_overrides_desc'] = 'JSON object na naka-key sa provider ng avatar na may iisang rate sa USD kada minuto. Pinapalitan nito ang nakabalot na rate para sa provider na iyon. Halimbawa: <pre>{ "did": 0.18, "heygen": 0.40, "tavus": 0.25 }</pre> Blangko = gamitin ang mga nakabalot na default ng v4.10.0: D-ID $0.30/min, HeyGen $0.50/min, Tavus $0.30/min, Synthesia $0.40/min. Itakda ito sa iyong kontratadong rate para maipakita ng analytics dashboard ang tunay na gastos ng institusyon.';
$string['settings:talking_avatar_did_webhook_secret'] = 'Webhook signing secret ng D-ID';
$string['settings:talking_avatar_did_webhook_secret_desc'] = 'Opsyonal. Kapag nakatakda, maaaring mag-POST ang D-ID ng mga event ng pagtatapos ng session sa <code>{wwwroot}/local/ai_course_assistant/talking_avatar_webhook.php?provider=did</code> na nilagdaan gamit ang secret na ito bilang <code>X-DID-Signature</code> (hex HMAC-SHA256). Nangunguna ang mga row ng webhook kaysa sa frontend heartbeat. Blangko = naka-off ang handler, ang heartbeat + oras-oras na sweeper ang eksklusibong humahawak sa pagtatapos ng session.';
$string['settings:talking_avatar_heygen_webhook_secret'] = 'Webhook signing secret ng HeyGen';
$string['settings:talking_avatar_heygen_webhook_secret_desc'] = 'Opsyonal. Kapag nakatakda, maaaring mag-POST ang HeyGen ng mga event ng pagtatapos ng session na nilagdaan gamit ang secret na ito bilang <code>X-HeyGen-Signature</code> (hex HMAC-SHA256). Blangko = naka-off ang handler.';
$string['settings:talking_avatar_tavus_webhook_secret'] = 'Webhook signing secret ng Tavus';
$string['settings:talking_avatar_tavus_webhook_secret_desc'] = 'Opsyonal. Kapag nakatakda, maaaring mag-POST ang Tavus ng mga event ng pagtatapos ng usapan na nilagdaan gamit ang secret na ito bilang <code>X-Tavus-Signature</code> (hex HMAC-SHA256). Blangko = naka-off ang handler.';
$string['settings:talking_avatar_synthesia_webhook_secret'] = 'Webhook signing secret ng Synthesia';
