$string['settings:prompt_debug_enabled']      = 'Log assembled system prompt to file';
$string['settings:prompt_debug_enabled_desc'] = 'When on, every chat-turn writes the full assembled system prompt and per-section character counts to <code>moodledata/temp/sola_prompt_debug.log</code> (rolling at ~1MB). Default off. Use to measure prompt size empirically and audit which sections contribute the most tokens. The log contains the system prompt only (no learner input or PII).';
$string['settings:socratic_verbose'] = 'Detalyadong prompt ng Socratic mode';
$string['settings:socratic_verbose_desc'] = 'Kapag naka-on, tumatanggap ang mga kursong nasa Socratic mode ng buong ~600-token na direktibang gawin/huwag gawin na orihinal na idinagdag sa v3.9.30. Kapag naka-off (default), tumatanggap sila ng isang linyang direktiba na maaasahang sinusunod ng mga makabagong hosted na modelo at nakakatipid ng ~600 token kada turn. I-on ito kung ang isang kurso ay tumatakbo sa mas mahinang self-hosted na modelo na nangangailangan ng tahasang scaffolding.';
$string['settings:prompt_budget_chars'] = 'Badyet ng character ng system prompt';
$string['settings:prompt_budget_chars_desc'] = 'Maximum total size of the assembled system prompt before the user message, in characters. The structured prompt builder organises sections by category (identity, course context, learner state, behaviour, markers, safety) and drops or truncates the lowest-priority sections when the budget is exceeded. Safety guidance is always preserved in full. Default 8,000 characters (~2,000 tokens). Lower values reduce per-turn cost; higher values allow more course content to land in-prompt.';
$string['settings:current_page_content_maxchars'] = 'Limitasyon sa nilalaman ng kasalukuyang pahina (mga character)';
$string['settings:current_page_content_maxchars_desc'] = 'Pinakamaraming bilang ng mga karakter ng teksto ng kasalukuyang pahina na inilalagay sa system prompt bilang seksyong "Current Page Content", kapag naka-off ang RAG. Ang default na 8,000 ay maayos na sumusuporta sa mga tanong na tiyak sa pahina habang nag-iiwan ng budget para sa istraktura at mga tagubilin. (Kapag naka-enable ang RAG, ang pahina ay sa halip ay sinusuportahan ng sarili nitong pinaka-nauugnay na mga chunk, na may bias sa kasalukuyang pahina, kaya hindi naaangkop ang cap na ito.) Ang isang napakahabang pahina ay puputulin mula sa simula hanggang sa ganito karaming karakter, kaya maaaring hindi masipi ang dulo ng isang sobrang habang pahina; ang pag-enable ng RAG ay umiiwas dito. Ang mga site na maingat sa gastos ay maaaring magtakda ng mas mababa (hal. 3,000-4,000). Nililimitahan sa saklaw na 500-8,000. Hiwalay sa <code>prompt_budget_chars</code>: nililimitahan lamang nito ang seksyon ng pahina; ang budget ay nililimitahan ang buong prompt.';
$string['settings:prompt_verbosity'] = 'Pagkadetalyado ng prompt';
$string['settings:prompt_verbosity_desc'] = 'Default na pagkadetalyado para sa mga bloke ng tagubilin (Socratic mode, mga panlabas na mapagkukunan). Ang Maikli (default) ang maaasahang sinusunod ng mga makabagong hosted na modelo; ang Karaniwan ay nagdaragdag ng tahasang scaffolding para sa mga mid-tier na modelo; ang Detalyado ay pinapanatili ang mabigat na gabay mula sa panahon ng v3.9.30 para sa mas mahihinang self-hosted na modelo. May available na per-course override sa pamamagitan ng <code>prompt_verbosity_course_&lt;id&gt;</code>.';
$string['settings:prompt_verbosity_concise'] = 'Maikli (inirerekomenda para sa mga hosted na modelo)';
$string['settings:prompt_verbosity_standard'] = 'Karaniwan';
$string['settings:prompt_verbosity_verbose'] = 'Detalyado (para sa mas mahihinang self-hosted na modelo)';
$string['settings:prompt_metrics_enabled'] = 'Kunin ang mga sukatan ng prompt kada seksyon';
$string['settings:prompt_metrics_enabled_desc'] = 'Kapag naka-on (default), ang bawat chat turn ay nagsusulat ng isang linyang JSON kada binuong prompt sa <code>moodledata/sola_prompt_metrics/YYYY-MM-DD.log</code> kasama ang bilang ng character kada kategorya. Ang huling 7 araw ang itinatago. Pinagsasama-sama ito ng admin page ng mga sukatan para sa rekomendasyon sa badyet. Walang naitatalang PII — mga laki lamang ng seksyon. I-off kung mas gusto ng iyong institusyon na walang metrics file kahit kailan.';
$string['settings:prompt_budget_auto_tune'] = 'Araw-araw na awtomatikong pag-aayos ng badyet ng system prompt (hindi na ginagamit)';
$string['settings:prompt_budget_auto_tune_desc'] = 'Hindi na ginagamit. Wala itong ginagawa maliban kung ang mode ng badyet sa itaas ay nakatakda sa <strong>Nakatakda</strong>. May araw-araw na gawain na humuhula sa badyet ng karakter sa pamamagitan ng pagsubaybay sa pagputol at paghahabol sa pinakamalaking prompt na nakita nito. Ang paghango ng badyet mula sa context window ng modelo ay mas mahusay: hindi ito umuugoy at hindi nangangailangan ng panimulang datos. Nagkasalungat din ang dalawa, dahil isinusulat ng gawain ang badyet ng karakter at ang anumang halagang bukod sa default ay nag-o-off sa hinangong badyet. Iwanan itong naka-off; aalisin sa susunod na bersyon. Lumalabas pa rin ang rekomendasyon sa pahinang <a href="/local/ai_course_assistant/prompt_metrics.php">Sukatan ng prompt</a>.';
$string['task:auto_tune_prompt_budget'] = 'Awtomatikong i-tune ang prompt budget ng [[tutorshort]] mula sa mga naobserbahang sukatan';
$string['prompt_metrics:title'] = 'Prompt metrics + rekomendasyon sa badyet';
$string['prompt_metrics:subtitle'] = 'Mga laki ng prompt bawat seksyon na nakuha sa nakalipas na 7 araw. Ginagamit para magrekomenda ng halaga para sa setting na badyet ng karakter ng system prompt.';
$string['prompt_metrics:no_data'] = 'Wala pang naitalang prompt metrics. Magpadala ng ilang chat turn mula sa isang account ng mag-aaral, pagkatapos ay i-refresh ang pahinang ito. (Kung naka-off ang flag ng pagkuha ng metrics sa mga setting ng plugin, walang datos na maiipon.)';
