$string['task:milestone_check'] = 'Magpadala ng araw-araw na milestone reflection na email (v5.3.0)';
$string['task:struggle_signal_review'] = 'Suriin ang mga struggle signal tungo sa pribadong memorya ng mag-aaral (v5.3.0)';
$string['empathy:title'] = 'Mga empathetic na komunikasyon at carryover na memorya (v5.3.0)';
$string['empathy:desc'] = 'Tatlong magkaugnay na feature na nagpapadama sa [[tutorshort]] na tila isang coach na nakikinig. Kinukuha ng mga layunin kung bakit narito ang mag-aaral. Naaalala ng carryover na memorya kung ano ang naging mahirap noon para makapag-alok ang [[tutorshort]] ng ibang anggulo. Ipinagdiriwang ng mga milestone ang mga sunod-sunod na araw at mga pagtatapos sa pamamagitan ng email. May sariling kill switch ang bawat feature at kailangang mag-opt in ang mag-aaral. Hindi kailanman lumalabas sa chat ang mga senyales ng hirap — walang email na ipinapadala tungkol sa isang mahirap na sesyon.';
$string['empathy:outreach_master_enabled'] = 'Master kill switch ng outreach';
$string['empathy:outreach_master_enabled_desc'] = 'Naka-off bilang default sa isang bagong installation. Kapag naka-off, WALANG anumang empathetic na email ang ipapadala, anuman ang mga switch ng bawat feature sa ibaba. I-on ito kapag nasuri mo na ang mga default ng bawat feature at ang daloy ng pahintulot ng bawat mag-aaral.';
$string['empathy:goals_enabled'] = 'I-enable ang mga usapan tungkol sa layunin sa karera';
$string['empathy:goals_enabled_desc'] = 'Pinapayagan ang mga mag-aaral na kusang magbigay ng dalawang maikling sagot (kung bakit sila narito, kung ano ang gusto nilang maging) na ginagamit sa personalization. Sa chat lamang; walang email. Ligtas na iwang naka-on.';
$string['empathy:milestones_enabled'] = 'I-enable ang mga email ng pagninilay sa milestone';
$string['empathy:milestones_enabled_desc'] = 'Nagpapadala ng maikli at magiliw na email kapag naabot ng mag-aaral ang 7-araw na sunod-sunod, 30-araw na sunod-sunod, o ang pagtatapos ng kurso. Kailangan ang master switch sa itaas kasama ang pahintulot ng bawat mag-aaral. Mahigpit na limitasyon na isang email bawat mag-aaral kada 7 araw sa lahat ng channel.';
$string['empathy:memory_enabled'] = 'I-enable ang carryover na memorya para sa personalization';
$string['empathy:memory_enabled_desc'] = 'Pinapayagan ang [[tutorshort]] na magdala ng maliliit na pribadong tala tungkol sa kung ano ang naging mahirap para sa isang mag-aaral sa iba\'t ibang sesyon, para makapag-alok ng ibang anggulo ang susunod na tugon. May hangganan (hanggang 5 tala bawat mag-aaral bawat kurso, 90-araw na TTL). Mae-edit ng mag-aaral. Hindi kailanman nakikita ng mga instruktor.';
$string['empathy:struggle_enabled'] = 'I-enable ang tagatukoy ng hirap sa pag-aaral';
$string['empathy:struggle_enabled_desc'] = 'Naka-off bilang default. Pinapayagan ang [[tutorshort]] na matukoy ang tuloy-tuloy na pagkadismaya sa maraming sagutan at tahimik na magtala ng nota tungkol sa sagabal sa carryover na memorya sa itaas. Ang output ay nasa chat lamang; walang email na ipinapadala tungkol sa isang sesyon ng hirap. Awtomatikong binubura ang datos ng senyales pagkatapos ng 7 araw.';
$string['empathy:outreach_dryrun'] = 'Dry-run na outreach (itala nang hindi nagpapadala)';
$string['empathy:outreach_dryrun_desc'] = 'Kapag naka-on, nagtatala ang naka-iskedyul na gawain para sa milestone ng mga audit row na para bang nagpadala ito ng mga email ngunit walang aktuwal na ipinapadala kaninuman. Gamitin ito sa isang bagong installation para mapatunayan ang lohika ng cooldown at ng pahintulot bago ito ilabas nang tuluyan.';
