// v5.10.x strings (token-aware budgeting, backend retry, self-test, deployment presets, escalation consent, privacy).
$string['settings:backend_context_tokens'] = 'Window ng konteksto ng backend (mga token)';
$string['settings:backend_context_tokens_desc'] = 'Ang pinakamataas na haba ng konteksto (max_model_len) ng iyong AI backend, sa mga token. Itakda sa 0 para sa mga naka-host na modelo na may malaking window (walang clamping). Kapag itinakda nang higit sa 0 (halimbawa, 8192 sa isang self-hosted na vLLM backend), pinapaliit ng [[tutorshort]] ang badyet ng karakter ng system-prompt sa itaas upang ang prompt kasama ang nakareserbang output at kasaysayan ng usapan ay magkasya sa window, kahit sa mga wikang masinsin ang token. Tingnan ang pahina ng wiki na Deployment Sizing kung paano ito tumutugma sa mga sabay-sabay na user.';
$string['settings:backend_retry_attempts'] = 'Mga pagtatangkang i-retry ang backend';
$string['settings:backend_retry_attempts_desc'] = 'Kung ilang beses i-retry ang isang panandaliang error ng backend (HTTP 429 o 503) bago ipakita sa estudyante ang isang error. Ang mga retry ay nangyayari lamang bago pa man na-stream ang anumang teksto ng tugon, kaya hindi kailanman nagdo-doble ang output. Nakatuon sa maliliit na self-hosted na backend na tumatanggi sa mga kahilingan sa ilalim ng load. Itakda sa 0 upang i-disable. Default na 2.';
$string['settings:backend_retry_max_wait'] = 'Pinakamataas na paghihintay sa pag-retry ng backend (mga segundo)';
$string['settings:backend_retry_max_wait_desc'] = 'Ang pinakamataas na hangganan, sa mga segundo, kung gaano katagal igagalang ang isang Retry-After header mula sa backend bago mag-retry. Kapag hindi nagpadala ng Retry-After ang backend, gumagamit ang [[tutorshort]] ng maikling exponential backoff sa halip. Default na 5.';
$string['prompt:truncation_hint'] = 'TANDAAN: Hindi nahanap ang buong nilalaman ng kurso sa pagkakataong ito dahil sa mga limitasyon sa haba. Kung magtanong ang estudyante tungkol sa isang bagay na hindi mo makita sa ibinigay na nilalaman, sabihin na hindi mo nasaliksik ang buong kurso at imungkahi na buksan nila ang partikular na pahina o aktibidad kung saan tinatalakay ang paksa, sa halip na sabihing wala ito sa kurso.';
$string['selftest:title'] = 'Self-test ng backend';
$string['selftest:intro'] = 'Magpatakbo ng live na pagsusuri ng iyong naka-configure na AI backend: isang maliit na round-trip ng chat, awtomatikong pagtukoy ng window ng konteksto (max_model_len) at isang paghahambing laban sa iyong setting ng window ng konteksto ng backend, ang floor ng badyet ng system-prompt, at (kapag naka-on ang RAG) isang round-trip ng embedding. Tumatakbo lamang ang mga tawag sa network kapag pinindot mo ang Patakbuhin.';
$string['selftest:run'] = 'Patakbuhin ang self-test ng backend';
$string['selftest:check'] = 'Suriin';
$string['selftest:status'] = 'Katayuan';
$string['selftest:detail'] = 'Detalye';
$string['selftest:link'] = 'Pahina ng self-test ng backend';
$string['selftest:link_desc'] = 'Buksan ang pahina ng <a href="{$a}">Self-test ng backend</a> upang i-verify na gumagana at tama ang laki ng iyong AI backend. Kapaki-pakinabang kaagad pagkatapos i-configure ang isang self-hosted na backend.';
$string['profile:title'] = 'Mga preset ng deployment';
$string['profile:intro'] = 'Maglapat ng inirerekomendang bundle ng mga setting para sa iyong uri ng deployment. Ang mga halaga ay isinusulat sa karaniwang mga setting ng plugin at nananatiling indibidwal na nae-edit pagkatapos. Ang paglalapat ng preset ay nag-o-overwrite sa mga nakalistang setting.';
$string['profile:current'] = 'Huling inilapat na preset: {$a}';
$string['profile:setting'] = 'Setting';
$string['profile:value'] = 'Halaga';
$string['profile:self_hosted_small'] = 'Self-hosted na maliit na konteksto (isang GPU, hal. A30 24GB / vLLM sa 8K)';
$string['profile:hosted_large'] = 'Naka-host na malaking konteksto (default)';
$string['profile:apply_self_hosted_small'] = 'Ilapat ang preset ng self-hosted na maliit na konteksto';
$string['profile:apply_hosted_large'] = 'Ilapat ang mga default ng naka-host na malaking konteksto';
$string['profile:applied'] = 'Inilapat ang preset na {$a}. Nasa iyong mga setting ng plugin na ngayon ang mga halaga.';
$string['profile:unknown'] = 'Hindi kilalang preset ng deployment.';
$string['profile:link'] = 'Pahina ng mga preset ng deployment';
$string['profile:link_desc'] = 'Buksan ang pahina ng <a href="{$a}">Mga preset ng deployment</a> upang maglapat ng inirerekomendang bundle ng mga setting para sa isang naka-host o self-hosted na backend.';
$string['coursesettings:apibaseurl_rejected'] = 'Hindi na-save ang base URL ng API: dapat itong pampublikong HTTPS endpoint na pumapasa sa pagsusuri sa kaligtasan laban sa SSRF.';
$string['settings:escalation_intent_patterns'] = 'Mga pattern ng intensyong mag-escalate';
$string['settings:escalation_intent_patterns_desc'] = 'PCRE, no delimiters. Isang regular expression bawat linya; binabalewala ang mga linyang nagsisimula sa #. Bubuksan lamang ang support ticket kapag tumugma ang sariling mensahe ng mag-aaral sa isa sa mga ito, kaya hindi maaaring mag-udyok ng escalation ang nilalaman ng kurso sa ngalan ng mag-aaral. Iwanang blangko upang gamitin ang mga built-in na default, na sumasaklaw sa Ingles at ilang karaniwang pahayag sa Espanyol, Pranses, Aleman at Portuges. Ang mga site na ang mga mag-aaral ay sumusulat sa ibang wika ay dapat magdagdag ng mga pattern dito: ang mensaheng walang tugma ay nangangahulugang walang ticket na bubuksan.';
$string['settings:zendesk_require_consent'] = 'Mangailangan ng pahintulot bago ang escalation ng suporta';
$string['settings:zendesk_require_consent_desc'] = 'Kapag naka-on (inirerekomenda), ine-escalate lamang ng [[tutorshort]] ang isang usapan sa Zendesk support desk pagkatapos tanggapin ng mag-aaral ang first-run na abiso ng pahintulot, na nagbubunyag na ang paghingi ng tulong ng tao ay nagbabahagi ng usapan (kasama ang pangalan at email) sa suporta. I-off lamang ito kung makukuha mo ang pahintulot na iyon sa ibang paraan; kapag naka-off, agad na ipinapadala ang mga escalation. Walang epekto maliban kung naka-enable ang escalation ng Zendesk.';
$string['chat:escalation_needs_consent'] = 'Mukhang kailangan nito ng isang miyembro ng aming koponan ng suporta. Upang maipasa ito sa kanila, kailangan kong ibahagi ang usapang ito, kasama ang iyong pangalan at email, sa support desk. Hindi mo pa ito napapayagan, kaya wala pa akong ipinadala. Kung nais mo ng tulong ng tao, mangyaring tanggapin ang abiso ng pagbabahagi ng data para sa assistant na ito at magtanong muli, o makipag-ugnayan nang direkta sa suporta.';
$string['privacy:metadata:email_optout'] = 'Mga kagustuhan sa pag-opt-out ng email kada-recipient (kung aling mga uri ng email ang na-unsubscribe ng isang recipient).';
$string['privacy:metadata:email_optout:email'] = 'Ang email address ng recipient kung saan nalalapat ang opt-out.';
$string['privacy:metadata:email_optout:optout_type'] = 'Ang uri ng email na inopt-out ng recipient.';
$string['privacy:metadata:email_optout:userid'] = 'Ang Moodle user na pag-aari ng opt-out, kapag alam.';
$string['chat:consent_scroll_hint'] = 'Mangyaring mag-scroll pababa upang basahin ang buong abiso bago magpatuloy.';
$string['settings:rag_min_similarity'] = 'Pinakamababang Kaugnayan (cosine)';
$string['settings:rag_min_similarity_desc'] = 'I-drop ang mga nakuhang chunk na ang cosine similarity sa tanong ay mas mababa sa halagang ito, para ang isang off-topic o kakaunti ang impormasyong tanong ay maglagay ng mas kaunting (o walang) talata sa halip na laging magpuno hanggang Top-K gamit ang mahihinang tugma. Saklaw 0 hanggang 1; ang 0 ay nag-disable sa gate. Ang tamang halaga ay nakadepende sa embedding model: ang 0.25 ay angkop sa text-embedding-3-small. Itaas ito para maging mas mahigpit (mas kaunti, mas naaangkop na konteksto), ibaba ito para maging mas mapagbigay.';
$string['settings:rag_currentpage_boost'] = 'Boost ng Kasalukuyang Pahina';
$string['settings:rag_currentpage_boost_desc'] = 'Isang maliit na bonus na idinadagdag sa relevance score ng mga chunk mula sa pahinang kasalukuyang tinitingnan ng mag-aaral, para ang mga tanong tulad ng "ipaliwanag ito" ay mas pinapaboran ang nakikitang pahina kapag malapit ang mga score. Pag-aayos lamang: hindi nito pinipilit ang isang hindi nauugnay na chunk ng pahina na lumampas sa minimum-relevance gate. Itakda sa 0 para i-disable.';
$string['settings:history_mode'] = 'Mode ng Pagpili ng Kasaysayan';
$string['settings:history_mode_desc'] = 'Kung paano pinipili ang mga nakaraang turn ng usapan bago ipadala sa modelo. Ang <strong>Semantic</strong> ay pinapanatili lamang ang mga kamakailang turn na nauugnay sa kasalukuyang tanong (at palaging ang pinakabagong palitan), para ang isang luma at off-topic na naunang turn ay hindi magpataas ng gastos o maglihis ng sagot; nagsasagawa ito ng isang dagdag na embedding call kada mensahe. Ang <strong>Recency</strong> ay pinapanatili ang huling "Max Conversation History" na pares anuman ang kaugnayan (ang matagal nang pag-uugali, walang dagdag na call). Kung hindi available ang embedding, ang semantic mode ay awtomatikong babalik sa recency.';
$string['settings:history_mode_semantic'] = 'Semantic (nauugnay na kamakailang turn)';
$string['settings:history_mode_recency'] = 'Recency (huling N na pares)';
$string['settings:history_semantic_minscore'] = 'Sahig ng Kaugnayan ng Kasaysayan (cosine)';
$string['settings:history_semantic_minscore_desc'] = 'Sa semantic history mode, ang isang nakaraang turn ay pinapanatili lamang kung ang similarity nito sa kasalukuyang tanong ay hindi bababa sa halagang ito (palaging pinapanatili ang pinakabagong palitan). Saklaw 0 hanggang 1; nakadepende sa modelo. Itaas para maging mas mahigpit (mas kaunting kasaysayan), ibaba para magpanatili ng mas marami.';
$string['settings:history_candidates'] = 'Window ng Kandidatong Kasaysayan';
$string['settings:history_candidates_desc'] = 'Sa semantic history mode, tanging ang pinakabagong ganito-karaming pares lamang ang sinusuri para sa kaugnayan (isang hangganan ng gastos). Ang mga pares na mas luma sa window na ito ay hindi ipinapadala. Panatilihin ito na katumbas o higit pa sa "Max Conversation History".';

// v5.11.0 - v6.2.0 strings (added 2026-06-10).
$string['settings:embed_provider_voyage'] = 'Voyage AI (voyage-3.5 — inirerekomenda; +4 MTEB kumpara sa OpenAI 3-small, 4x na konteksto, multilingual)';
$string['settings:rerank_heading'] = 'RAG: Two-stage retrieval (re-ranking)';
$string['settings:rerank_heading_desc'] = 'Opsyonal na pangalawang yugto ng retrieval: pinipili ng cosine similarity ang mga nangungunang-N candidate chunk (default na 50), pagkatapos ay bino-score ng cross-encoder re-ranker ang bawat pares ng (query, chunk) at ang pinakamahusay na top-K ang pumupunta sa prompt. Naka-off bilang default; bumabalik sa single-stage cosine kung ang re-ranker ay hindi naka-configure o nabigo.';
$string['settings:rerank_enabled'] = 'Two-stage retrieval (Voyage rerank-2.5)';
$string['settings:rerank_enabled_desc'] = 'Kapag naka-enable, ang RAG retrieval ay nagiging two-stage: ibinabalik ng cosine similarity ang mga nangungunang-N kandidato (default na 50), pagkatapos ay bino-score ng Voyage rerank-2.5 cross-encoder ang bawat isa at ang top-K ang pumupunta sa prompt. Mga nai-publish na pagpapabuti: +15 Recall@10 enterprise, +39% NDCG BEIR. Tungkol sa ~$0.05/MTok na bayarin. Nangangailangan ng <code>rerank_apikey</code> sa ibaba; bumabalik nang maayos sa single-stage cosine kung nabigo o hindi naka-configure ang rerank.';
$string['settings:rerank_apikey'] = 'Rerank API key';
$string['settings:rerank_apikey_desc'] = 'Voyage AI API key para sa rerank-2.5. Iwanang blangko upang muling gamitin ang Embedding API Key sa itaas (karaniwang nagbabahagi ang mga Voyage deployment ng isang key sa embed + rerank).';
$string['settings:rerank_model'] = 'Rerank model';
$string['settings:rerank_model_desc'] = 'Default na <code>rerank-2.5</code>. Maaaring tukuyin dito ang mga mas bagong Voyage rerank model.';
$string['settings:rerank_apibaseurl'] = 'Rerank API base URL';
$string['settings:rerank_apibaseurl_desc'] = 'I-override ang Voyage rerank base URL. Iwanang blangko upang gamitin ang Embedding API Base URL sa itaas, o ang default ng Voyage (<code>https://api.voyageai.com/v1</code>).';
$string['settings:rerank_candidates'] = 'Rerank candidate window';
$string['settings:rerank_candidates_desc'] = 'Ilang cosine top-N na kandidato ang ipinapasok sa yugto ng pagre-rank muli. Default 20. Sinukat sa 1,008 na tanong: katumbas ng 30 ang 20 sa recall (R@3 89.0% kumpara sa 89.3%) sa isang-katlong mas mababang gastos, at 2.5 beses na mas mahal ang 50 nang walang masusukat na pakinabang. Sa ilalim ng 10, bumababa ang recall. Lumalaki ang gastos nang linear kasabay ng halagang ito.';
$string['settings:stt_selfhosted_heading'] = 'Self-hosted na transcription (Whisper)';
$string['settings:stt_selfhosted_heading_desc'] = 'Patakbuhin ang speech-to-text sa sarili mong hardware nang walang gastos bawat minuto. Ituro ang [[tutorshort]] sa anumang OpenAI-compatible na transcription server: <code>whisper-server</code> Docker, <code>speaches</code> (faster-whisper), o <code>whisper.cpp</code> server. Kapag nagtakda ng server URL dito, ito ang magiging default na STT path; pumili ng bayad na provider sa Active STT provider sa itaas upang i-override. Kung ang server ay nasa isang pribadong network o plain http, idagdag din ang host nito sa SSRF trusted endpoints allowlist sa seksyon ng Seguridad.';
$string['settings:stt_selfhosted_url'] = 'Selfhosted STT server URL';
$string['settings:stt_selfhosted_url_desc'] = 'Base URL ng OpenAI-compatible na transcription server, halimbawa <code>http://10.0.0.5:8000</code>. Awtomatikong idinaragdag ng [[tutorshort]] ang <code>/v1/audio/transcriptions</code>; tinatanggap din ang buong endpoint path. Iwanang blangko upang i-disable ang selfhosted STT.';
$string['settings:stt_selfhosted_model'] = 'Selfhosted STT model';
$string['settings:stt_selfhosted_model_desc'] = 'Pangalan ng model na ipinadala sa server, tumutugma sa Whisper model na na-load nito — halimbawa <code>Systran/faster-whisper-small</code> para sa speaches o <code>large-v3</code>. Iwanang blangko upang magpadala ng <code>whisper-1</code>, na karaniwang tinatanggap o binabalewala ng karamihang self-hosted na server.';
$string['settings:stt_selfhosted_apikey'] = 'Selfhosted STT API key';
$string['settings:stt_selfhosted_apikey_desc'] = 'Opsyonal. Karamihang self-hosted na server ay walang key sa likod ng isang pinagkakatiwalaang network; itakda ito kung nangangailangan ng bearer token ang iyong server.';
$string['emergency:title'] = '[[tutorshort]] Emergency Controls';
$string['emergency:page_warning'] = 'Ang mga switch na ito ay magkakabisa kaagad para sa bawat mag-aaral sa site. Ang bawat aksyon ay nagsusulat ng isang audit row. Ang mga granular na switch ay pinapanatiling tumatakbo ang natitirang [[tutorshort]]; tinatanggal ng master kill ang widget nang buo.';
$string['emergency:back_to_settings'] = '[[tutorshort]] Settings';
$string['emergency:state_disabled'] = 'HINDI PINAGANA';
$string['emergency:state_active'] = 'Aktibo';
$string['emergency:confirm_label'] = 'Naiintindihan ko na nakakaapekto ito sa bawat mag-aaral kaagad';
$string['emergency:confirm_required'] = 'Mangyaring lagyan ng tsek ang confirmation checkbox bago i-disable ang isang subsystem.';
$string['emergency:reason_placeholder'] = 'Dahilan (nire-record sa audit log)';
$string['emergency:disable_button'] = 'I-disable';
$string['emergency:restore_button'] = 'I-restore';
$string['emergency:disabled_notice'] = 'Ang subsystem na "{$a->flag}" ay na-disable. Naabot ang config: {$a->touched}';
$string['emergency:restored_notice'] = 'Ang subsystem na "{$a->flag}" ay na-restore. Naabot ang config: {$a->touched}';
$string['emergency:cli_reference'] = 'Ang parehong mga kontrol ay available mula sa on-call shell:';
$string['emergency:flag_chat'] = 'Chat';
$string['emergency:flag_chat_desc'] = 'Hinihinto ang lahat ng tawag sa AI ng [[tutorshort]] — chat, pagsusulit, flashcard at pagmamarka — para sa mga mag-aaral, administrador at nakatakdang gawain nang pantay. Nananatiling lumalabas ang widget at nakikita ng mga mag-aaral ang maikling paunawa ng pag-pause. Nananatiling available ang backend self-test at health check para masuri ang provider bago magbalik.';
$string['emergency:flag_voice'] = 'Boses';
$string['emergency:flag_voice_desc'] = 'Nili-clear ang aktibong realtime voice provider (nakatago para sa eksaktong pag-restore). Patuloy na gumagana ang text chat.';
$string['emergency:flag_rag'] = 'RAG';
$string['emergency:flag_rag_desc'] = 'Dina-disable ang retrieval at indexing. Nagpapatuloy ang chat nang walang course-content grounding.';
$string['emergency:flag_outreach'] = 'Outreach';
$string['emergency:flag_outreach_desc'] = 'Itinatigil ang digest, milestone, at reminder na mga email. Hindi naaapektuhan ang chat.';
$string['emergency:flag_all'] = 'MASTER KILL';
$string['emergency:flag_all_desc'] = 'Dina-disable ang buong plugin: wala nang widget sa bawat pahina, tumitigil ang mga naka-iskedyul na gawain, nali-clear ang boses, naka-off ang RAG, naka-off ang outreach. Ang pinakamalakas na switch — gamitin para sa isang insidente sa seguridad o kapag kailangang dalhin ang [[tutorshort]] offline kaagad.';
$string['emergency:settings_link'] = 'Mga emergency control';
$string['emergency:settings_link_desc'] = 'Mga per-subsystem na kill switch (chat / boses / RAG / outreach / master) na may audit logging — ang web equivalent ng <code>admin/cli/emergency_disable.php</code>. Buksan ang <a href="{$a}">[[tutorshort]] Emergency Controls</a>.';
$string['email_unsubscribe:done_title'] = 'Na-unsubscribe';
$string['email_unsubscribe:done_body'] = 'Tapos na — hindi na makakatanggap ang {$a->email} ng ganitong uri ng email mula sa {$a->product}. Kung magbabago ang isip mo, hilingin sa isang administrator ng {$a->product} na muling i-enable ang subscription, o magpadala ng bagong opt-in sa pamamagitan ng pahina ng [[tutorshort]] Recipients admin.';
$string['email_unsubscribe:invalid_title'] = 'Hindi na wasto ang link ng pag-unsubscribe';
$string['email_unsubscribe:invalid_body'] = 'Ang link na ito ng pag-unsubscribe ay nag-expire na o mali ang format. Hanapin ang mas kamakailang email mula sa amin, o makipag-ugnayan sa isang administrator ng site upang manu-manong maalis.';
$string['settings:prompt_proportions_heading'] = 'Mga proporsyon ng seksyon ng prompt (v5.6.0)';
$string['settings:prompt_proportions_heading_desc'] = 'Ilaan ang badyet ng system prompt sa apat na bucket: kaligtasan + pagkakakilanlan, istraktura ng kurso, nilalaman ng kurso, at kasalukuyang pahina. Ang mga timbang ay mga porsyento na nagkakabuos ng 100. Ang mga empirikal na na-tune na default (10 / 10 / 40 / 40) ay nagmula sa v5.6.0 weight-tuning benchmark; ang pag-iwan ng blangko sa textarea ay gumagamit ng mga default na iyon. Ang awtomatikong boost ay nag-a-adjust ng alokasyon bawat turn depende kung nasa saklaw ang isang partikular na pahina.';
$string['settings:prompt_section_weights'] = 'Mga base na timbang ng seksyon (JSON)';
$string['settings:prompt_section_weights_desc'] = 'Opsyonal na JSON object na nagmamapa ng bawat bucket sa isang porsyento. Iwanang blangko upang gamitin ang mga na-benchmark na default (10 / 10 / 40 / 40). Halimbawa: <code>{"safety_identity": 10, "course_structure": 10, "course_content": 40, "current_page": 40}</code>. Ang mga timbang ay dapat magkabuos ng 100 (±5%). Ang <code>safety_identity</code> ay may floor na 10% upang ang jailbreak resistance at mga output-format marker ay laging nailalagay nang buo. Ang <code>current_page + course_content</code> ay dapat na hindi bababa sa 40% upang magkaroon ng sapat na materyal ang modelo. Ang mga out-of-range na halaga ay tahimik na bumabalik sa mga na-benchmark na default; dapat i-validate ng mga admin sa pamamagitan ng pagsuri sa prompt-debug log pagkatapos mag-save.';
$string['settings:prompt_context_boost_mode'] = 'Context boost mode';
$string['settings:prompt_context_boost_mode_desc'] = 'Awtomatikong pag-aayos na nagpapalipat ng timbang patungo sa seksyon ng kasalukuyang pahina kapag nasa saklaw ang isang partikular na pahina, at patungo sa nilalaman ng kurso kapag walang napiling pahina. Ang <strong>page_focus</strong> (default) ay nagpapalipat ng humigit-kumulang 15 puntos ng timbang. Ang <strong>aggressive</strong> ay nagpapalipat ng 25 puntos at pinakamahusay kapag ang mga mag-aaral ay patuloy na nagtatanong ng mga tanong na tukoy sa pahina. Ang <strong>off</strong> ay dina-disable ang boost; ang mga admin-set na base na timbang ay nalalapat sa bawat turn anuman ang konteksto ng pahina.';
$string['settings:prompt_context_boost_off'] = 'Off (gamitin ang mga base na timbang sa bawat turn)';
$string['settings:prompt_context_boost_page_focus'] = 'Page focus (default, ~15 puntos na paglipat)';
$string['settings:prompt_context_boost_aggressive'] = 'Aggressive (~25 puntos na paglipat)';
$string['settings:prompt_section_weights_coach'] = 'Coach-mode override (JSON, opsyonal)';
$string['settings:prompt_section_weights_coach_desc'] = 'Opsyonal na JSON object na nag-o-override ng mga base na timbang ng seksyon partikular sa panahon ng graded-quiz coach mode (kapag <code>quizmode=coach</code>). Kapaki-pakinabang para sa pagpilit ng mas mabigat na alokasyon ng <code>current_page</code> sa panahon ng mga pagsusulit nang hindi naaapektuhan ang normal na chat. Iwanang blangko upang mamanahin ang mga base na timbang. Parehong mga patakaran ng validation tulad ng base na setting.';
$string['prompt_debug_view:title'] = 'Prompt debug log viewer';
$string['prompt_debug_view:subtitle'] = 'Per-turn na naka-assemble na system prompt + per-section breakdown + kasaysayan ng pakikipag-usap + kasalukuyang mensahe ng user + attachment metadata, eksaktong tulad ng natanggap ng modelo. Gamitin ito upang i-verify kung ang isang seksyon tulad ng Current Page Content ay talagang napunta sa prompt at upang i-debug ang mga isyu sa kalidad ng sagot nang hindi kailangang mag-SSH sa server.';
$string['prompt_debug_view:disabled'] = 'Ang prompt debug logging ay kasalukuyang NAKA-OFF. Walang bagong entry ang isusulat hanggang hindi ito naka-enable.';
$string['prompt_debug_view:enable_link'] = 'Buksan ang mga setting ng plugin upang i-enable ang "Log assembled system prompt to file".';
$string['prompt_debug_view:no_log_yet'] = 'Wala pang log file. Magpadala ng kahit isang chat turn pagkatapos i-enable ang debug log; ang file ay nililikha sa unang pagsusulat.';
