$string['settings:mastery_classifier_provider'] = 'Classifier provider';
$string['settings:mastery_classifier_provider_desc'] = 'Provider id na ginagamit para sa per-turn na mastery classifier. Iwanang blangko upang mamanahin ang default na AI provider. Ang default na <code>openai</code> ay nagpapares sa <code>gpt-4o-mini</code> classifier model sa ibaba — ang pinakamurang opsyon sa TIER 1 para sa structured-output classification (nakakatipid ng ~$220/buwan sa 100k MAU kumpara sa chat tier). Kapag nagtakda, ang row sa Comparison providers na may provider id na ito ay nagbibigay ng API key, base URL, at temperature.';
$string['settings:premium_escalation_heading'] = 'Premium escalation tier (A.10)';
$string['settings:premium_escalation_heading_desc'] = 'Opsyonal na per-turn na routing sa isang premium na modelo (Claude Opus 4.8 bilang default) para sa mga prompt kung saan nahihirapan ang workhorse chat tier — karaniwang multi-step na matematika, CS, at agham na pangangatuwiran. Nalutas ng A.10 bake-off noong 2026-06-09: nanalo ang Opus 4.8 sa 14.97/15 kumpara sa 12.68/15 ng gpt-4o sa mga mahirap na prompt. Dalawang trigger path: regex na tumutugma sa mensahe ng user, O isang course allowlist na nag-e-escalate sa bawat turn. Naka-off bilang default. Sa ~5% na escalation, asahan ang ~$700/buwan sa 100k [[unishort]] MAU sa tuktok ng baseline na gastos sa chat.';
$string['settings:premium_escalation_enabled'] = 'I-enable ang premium escalation routing';
$string['settings:premium_escalation_enabled_desc'] = 'Kapag naka-on, sinusuri ng per-turn na router ang listahan ng trigger regex at ang course allowlist para sa bawat chat call; ang mga naaayon na turn ay iniruruta sa premium provider. Bumabalik sa workhorse provider kung ang premium row ay nawawala o nabigo sa instantiating. Ang mga override ng admin-LLM-picker ay laging nangunguna anuman ang mangyari.';
$string['settings:premium_escalation_provider'] = 'Premium provider';
$string['settings:premium_escalation_provider_desc'] = 'Provider id na iru-route ng mga premium call. Dapat tumugma sa isang row sa Comparison providers (kaya ang API key, base URL, at temperature ay nagmumula sa parehong lugar na pinamamahalaan na ng mga admin). Default na <code>claude</code>.';
$string['settings:premium_escalation_model'] = 'Premium model';
$string['settings:premium_escalation_model_desc'] = 'Pangalan ng modelo na ipinapasa sa premium provider. Default na <code>claude-sonnet-5</code> ayon sa hatol ng A.10 bake-off.';
$string['settings:premium_escalation_triggers'] = 'Mga premium trigger regex';
$string['settings:premium_escalation_triggers_desc'] = 'Isang PCRE regex bawat linya (nang walang mga delimiter; awtomatikong inilalapat ang case-insensitive matching). Ang mga linya na nagsisimula sa # ay mga komento. Iwanang blangko upang gamitin ang curated na default na set mula sa A.10 bake-off (mga multi-step STEM marker: "derive", "prove that", "step by step", LaTeX math, fenced code block, big-O, integral, optimization, atbp.).';
$string['settings:premium_escalation_course_tags'] = 'Premium course allowlist';
$string['settings:premium_escalation_course_tags_desc'] = 'Isang course shortname o idnumber prefix bawat linya. Ang bawat turn sa isang naaangkop na kurso ay awtomatikong nag-e-escalate anuman ang regex ng mensahe (gamitin para sa mga kursong mabigat sa STEM kung saan ang escalation ay dapat maging default). Ang pagtutugma ay case-insensitive prefix — ang "MATH" ay tumutugma sa MATH121, MATH205, atbp.';
$string['settings:spend_cap_per_course_default'] = 'Default na limitasyon ng gastos bawat kurso (USD)';
$string['settings:spend_cap_per_course_default_desc'] = 'Depensibong limitasyon na inilalapat sa bawat kurso na walang sariling limitasyon ng gastos bawat kurso na naka-configure. Itakda sa hal. <code>30</code> upang limitahan ang buwanang gastos ng anumang iisang kurso sa $30 nang hindi kailangang i-tune ang mga indibidwal na kurso. Ang <code>0</code> = walang default (naaangkop lamang ang mga limitasyon sa buong site at per-course-override). Kapag lumampas ang isang kurso sa 80% / 95% / 100% ng limitasyong ito, nagpapadala ang umiiral na spend-guard alert pipeline ng abiso sa admin (listahan ng tatanggap: <code>spend_notify_emails</code>, bumabalik sa mga admin ng site). Maaaring palaging itaas ng isang partikular na kurso ang sarili nitong kisame sa pamamagitan ng pagtatakda ng mas mataas na per-course override.';
$string['settings:cost_anomaly_heading'] = 'Cost anomaly detector (v6.0)';
$string['settings:cost_anomaly_heading_desc'] = 'Araw-araw na naka-iskedyul na gawain (<code>cost_anomaly_check</code>) na naghahambing ng site-wide na gastos sa [[tutorshort]] ngayon laban sa rolling 7-day median. Nagpapadala ng email sa listahan ng tatanggap na <code>spend_notify_emails</code> (bumabalik sa mga admin ng site) kapag lumampas ang ngayon sa naka-configure na multiplier × median. Humahabol sa tatlong failure mode na hindi natutuklasan ng mga umiiral na 80% / 95% / 100% na threshold ng spend-cap: (1) runaway na kurso kung saan hindi naabot ang absolute na kisame ngunit isang kurso ang biglang nagtutulak ng 10x ng karaniwang dami nito, (2) aksidenteng pag-enable ng premium tier, (3) provider misroute. Naka-off bilang default; ang katumbas ng [[tutorshort]] ng Redash query sa <code>.drafts/sola-redash-cost-anomaly-2026-06-09.md</code>.';
$string['settings:cost_anomaly_enabled'] = 'I-enable ang cost anomaly detector';
$string['settings:cost_anomaly_enabled_desc'] = 'Kapag naka-on, sinusuri ng araw-araw na naka-iskedyul na gawain ang gastos ngayon laban sa rolling 7-day median at nagpapadala ng email sa mga admin sa anomalya. Ang unang 7 araw pagkatapos ng pag-enable ay nagpo-produce ng status na <code>insufficient_history</code> (wala pang historical na baseline) at hindi kailanman nag-eemit ng alerto. Idempotent bawat araw: ang isang flag sa <code>config_plugins</code> ay nagpipigil sa paulit-ulit na mga email kung ang cron ay tumakbo nang maraming beses.';
$string['settings:cost_anomaly_multiplier'] = 'Anomaly multiplier';
$string['settings:cost_anomaly_multiplier_desc'] = 'Ang gastos ngayon ay dapat lumampas sa multiplier na ito × ang 7-day median upang ma-trigger ang isang alerto. Default na <code>2.0</code>. Bawasan sa <code>1.5</code> para sa mas maagang mga babala (mas maraming false positive sa panahon ng mga enrollment burst). Itaas sa <code>3.0</code> kung ang paggamit ng [[unishort]] ay sapat na magulo upang ang 2x spike ay karaniwan.';
$string['task:cost_anomaly_check'] = '[[tutorshort]] cost anomaly check (araw-araw)';

// v6.4.0 signed policy bundle strings (added 2026-06-11).
$string['settings:policy_bundle_heading'] = 'Nilagdaang policy bundle (malalayong pag-update ng gawi)';
$string['settings:policy_bundle_heading_desc'] = 'Mag-apply ng mga setting ng gawi (mga prompt, routing, mga trigger ng escalation, pag-tune ng RAG, patakaran sa gastos) mula sa isang kriptograpikong nilagdaang JSON na file nang walang pag-deploy ng code. Ang isang araw-araw na naka-iskedyul na gawain ay kumuha ng bundle URL, bine-verify ang Ed25519 signature nito laban sa pampublikong key sa ibaba, at ina-apply ang mga setting lamang kung ang bawat key ay nasa built-in na allowlist at ang bersyon ng bundle ay mas bago kaysa sa huling na-apply. Ang mga API key, URL, webhook, at setting ng seguridad ay hindi kailanman maaaring itakda ng isang bundle. Gumawa at lagdaan ng mga bundle gamit ang <code>admin/cli/policy_bundle_tool.php</code> (keygen, sign, verify, status, sync).';
$string['settings:policy_bundle_enabled'] = 'I-enable ang policy bundle sync';
$string['settings:policy_bundle_enabled_desc'] = 'Kapag naka-enable, ang araw-araw na gawain ay kumukuha at nag-a-apply ng mga nilagdaang bundle. Naka-off bilang default. Ang pag-disable ay agad na nagtigil ng lahat ng sync; ang mga setting na na-apply na ay pinapanatili ang kanilang mga halaga.';
$string['settings:policy_bundle_url'] = 'URL ng policy bundle';
$string['settings:policy_bundle_url_desc'] = 'URL ng HTTPS ng nilagdaang bundle JSON (halimbawa isang S3 object o GitHub raw URL). Ang URL ay dumadaan sa parehong SSRF validation gaya ng mga AI provider endpoint; ang mga host ng pribadong network o plain-http ay nangangailangan ng entry sa SSRF trusted endpoints allowlist.';
$string['settings:policy_bundle_pubkey'] = 'Pampublikong key ng policy bundle';
$string['settings:policy_bundle_pubkey_desc'] = 'Base64 Ed25519 pampublikong key na ginagamit upang i-verify ang mga lagda ng bundle. Buuin ang keypair gamit ang <code>policy_bundle_tool.php --keygen</code>; ang pribadong key ay nananatili sa may-akda ng bundle at hindi kailanman dapat i-upload kahit saan.';
$string['settings:policy_bundle_status'] = 'Huling sync';
$string['settings:policy_bundle_applied_version'] = 'na-apply na bersyon';
$string['task:policy_bundle_sync'] = '[[tutorshort]] nilagdaang policy bundle sync';
$string['policy_bundle:invalid'] = 'Policy bundle tinanggihan: {$a}';
$string['prompt_debug_view:retrieved_chunks'] = 'Mga nakuhang chunk (pagpili ng RAG)';
$string['prompt_debug_view:retrieved_chunks_hint'] = 'Ang mga sipi na pinili ng retriever para sa tanong na ito, naka-ayos ayon sa ranggo kasama ang kanilang marka ng kaugnayan at pinagmulan (cmid). Gamitin ito upang i-verify na natanggap ng modelo ang pinakamatugmang nilalaman ng kurso.';
$string['settings:avatar_animation_enabled'] = 'Animasyon ng avatar';
