$string['settings:hidden_categories'] = 'Nakatagong mga kategorya ng kurso';
$string['settings:hidden_categories_desc'] = 'Listahan ng mga pangalan o ID ng kategorya ng kurso, pinaghihiwalay ng kuwit, kung saan hindi dapat lumitaw ang katuwang. Halimbawa: "Pagbuo ng kurso, 42". Awtomatiko ring nakatago ang katuwang kapag nakabukas ang editing mode.';
$string['settings:provider_heading'] = 'Tagapagbigay ng AI at pag-uusap';
