$string['settings:claude_temperature_allow_prefixes'] = 'Mga modelong Claude na sumusuporta sa parameter na temperature';
$string['settings:claude_temperature_allow_prefixes_desc'] = 'Isang unlapi ng pangalan ng modelo bawat linya. Ang mga modelo ng Anthropic na nagsisimula ang pangalan sa isa sa mga ito ay tumatanggap pa rin ng parameter ng sampling na <code>temperature</code>. Para sa anumang modelong Claude na hindi tumutugma sa alinmang unlapi, inaalis ang temperature (tinatanggihan ito ng mga reasoning model mula Opus 4.7 pataas gamit ang HTTP 400 na error). Iwanang blangko upang gamitin ang default na kasama ng plugin.';
$string['settings:max_tokens'] = 'Pinakamahabang sagot (mga token)';
$string['settings:max_tokens_desc'] = 'Pinakamataas na bilang ng token bawat sagot ng AI. Ang mas mababang halaga ay nagbibigay ng mas maikli at mas mabilis na sagot. 512 = mga 2-3 pangungusap, 1024 = mga 1-2 talata, 2048 = mas mahabang paliwanag. Itakda sa 0 kung walang limitasyon (ilalapat ang default ng tagapagbigay).';
$string['settings:profile_update_interval'] = 'Agwat ng pag-update ng profile ng mag-aaral';
$string['settings:profile_update_interval_desc'] = 'Pagkatapos ng ganitong bilang ng mensahe mula sa mag-aaral sa isang kurso, bubuo (o magre-refresh) ang katuwang ng profile ng pagkatuto na nagbubuod ng mga kalakasan, kahinaan, istilo ng pagkatuto, at interes. Isinasama ang profile sa system prompt para sa personalisadong sagot. Itakda sa 0 upang i-disable. Default: 10.';
$string['settings:enable_thinking'] = 'Pinalawak na pangangatwiran (Claude lamang)';
$string['settings:enable_thinking_desc'] = 'Binubuksan ang adaptive na pangangatwiran para sa mga modelong Claude. Ang Claude mismo ang nagpapasya kung kailan at gaano katagal pag-iisipan ang isang suliranin bago sumagot. Nagpapabuti ng katumpakan sa mga kumplikadong tanong, ngunit nagpapataas ng paggamit ng token at ng antala. Hindi ipinapakita sa mga mag-aaral ang nilalaman ng pangangatwiran. Binabalewala ng ibang tagapagbigay ang setting na ito.';
$string['settings:rag_sources_heading'] = 'Mga pinagkukunan ng nilalaman para sa RAG';
$string['settings:rag_sources_heading_desc'] = 'Piliin kung saang uri ng nilalaman ng kurso kukuha ng teksto ang RAG indexer. Ipinapakita ng mga tagapagpahiwatig ng katayuan sa <a href="{$a}">pahina ng pangangasiwa ng RAG</a> kung mayroon ang bawat extractor ng kailangan nito upang gumana (halimbawa ang kasangkapang pdftotext o ang allowlist ng Cloudflare).';
$string['settings:rag_extract_pdf'] = 'I-index ang mga PDF file (mod_resource)';
$string['settings:rag_extract_pdf_desc'] = 'Kumukuha ng teksto mula sa mga na-upload na PDF file sa pamamagitan ng kasangkapang <code>pdftotext</code> (poppler). Awtomatikong natutukoy ang landas ng kasangkapan; ituro ito sa ibaba kung kinakailangan.';
$string['settings:rag_pdftotext_path'] = 'Landas ng kasangkapang pdftotext';
$string['settings:rag_pdftotext_path_desc'] = 'Iwanang blangko para sa awtomatikong pagtukoy (sinusuri ang <code>/usr/bin/pdftotext</code>, <code>/usr/local/bin/pdftotext</code>, at <code>which pdftotext</code>). Punan lamang kung nasa ibang lugar ang inyong instalasyon.';
$string['settings:rag_extract_docx'] = 'I-index ang mga DOCX file (mod_resource)';
$string['settings:rag_extract_docx_desc'] = 'Kumukuha ng teksto mula sa mga na-upload na dokumentong Word sa pamamagitan ng ZipArchive ng PHP. Walang kailangang panlabas na dependency.';
$string['settings:rag_extract_pptx'] = 'I-index ang mga PPTX file (mod_resource)';
$string['settings:rag_extract_pptx_desc'] = 'Kumukuha ng teksto mula sa mga na-upload na makabagong presentasyong PowerPoint sa pamamagitan ng ZipArchive ng PHP. Dinadaanan ang XML ng mga slide at ng speaker notes ayon sa pagkakasunod-sunod ng slide; walang kailangang panlabas na dependency. Hindi sinusuportahan ang lumang binary na <code>.ppt</code> — i-save muli ang mga presentasyong iyon bilang <code>.pptx</code>.';
$string['settings:rag_extract_h5p'] = 'I-index ang nilalamang H5P (mod_h5p)';
$string['settings:rag_extract_h5p_desc'] = 'Dinadaanan ang JSON ng nilalamang H5P at ini-index ang lahat ng field na may teksto (mga tanong, sagot, feedback, paglalarawan). Malawak ang metadata ng mga uri ng nilalamang H5P; may inaasahang ilang maling tugma sa mga pambihirang kaso.';
$string['settings:rag_extract_scorm'] = 'I-index ang mga SCORM package (mod_scorm)';
$string['settings:rag_extract_scorm_desc'] = 'Binubuksan ang mga SCORM package at ini-index ang <code>imsmanifest.xml</code>, lahat ng <code>.html</code> file, at ang mga string ng nilalaman ng Articulate Storyline. <strong>Nakasara bilang default</strong>, dahil maaaring magastos ang pagproseso ng SCORM. Itinatakda ng <code>rag_scorm_max_mb</code> ang pinakamalaking sukat ng package.';
$string['settings:rag_scorm_max_mb'] = 'Pinakamalaking SCORM package na ii-index (MB)';
$string['settings:rag_scorm_max_mb_desc'] = 'Nilalaktawan ang mga SCORM package na mas malaki kaysa sa halagang ito upang maiwasan ang labis na paggamit ng memorya.';
$string['settings:rag_fetch_transcripts'] = 'Kunin ang mga transkripsyon para sa mga naka-embed na video at interactive na nilalaman';
$string['settings:rag_fetch_transcripts_desc'] = 'Sinusuri ang nilalaman ng mod_page at mod_book para sa mga naka-embed na iframe (Synthesia, YouTube, Articulate, Genially) at kinukuha ang address ng transkripsyong kasama ng bawat embed (naghahanap sa itaas at ibaba ng frame). Kailangan ng papalabas na koneksyong HTTPS mula sa server na ito patungo sa host ng transkripsyon. <strong>Nakasara bilang default</strong>; buksan matapos idagdag ng tagapagbigay ng transkripsyon ang server na ito sa kanilang allowlist (halimbawa sa pamamagitan ng panuntunan ng Cloudflare batay sa IP).';
$string['settings:rag_iframe_host_patterns'] = 'Mga pattern ng host ng iframe';
$string['settings:rag_iframe_host_patterns_desc'] = 'Isang regular expression bawat linya, itinutugma sa attribute na <code>src</code> ng isang iframe. Bawat tumutugmang frame ay itinuturing na interactive na embed na dapat pagtambalin at i-index ang transkripsyon. Ang mga linyang nagsisimula sa <code>#</code> ay mga komento.';
$string['settings:rag_transcript_url_pattern'] = 'Pattern ng address ng transkripsyon';
$string['settings:rag_transcript_url_pattern_desc'] = 'Regular expression na tumutugma sa mga address ng link ng transkripsyon. Para sa bawat natukoy na iframe, pinipili ng indexer ang pinakamalapit na tumutugmang link (sa itaas o ibaba nito) at pinagtatambal ang dalawa. Iwanang blangko upang isara ang pagtatambal ng transkripsyon.';
$string['settings:performance_heading'] = 'Pagganap';
$string['settings:performance_heading_desc'] = 'Kinokontrol kung gaano karaming nilalaman ng kurso ang isasama sa prompt para sa AI. Ang mas mababang halaga ay nangangahulugang mas mabilis na sagot ngunit mas kaunting konteksto para sa AI.';
$string['settings:max_content_per_resource'] = 'Pinakamaraming nilalaman bawat mapagkukunan (mga karakter)';
$string['settings:max_content_per_resource_desc'] = 'Pinakamataas na bilang ng karakter ng nilalamang kinukuha sa bawat pahina o kabanata ng aklat. Binabawasan ng mas mababang halaga ang laki ng prompt at pinapabilis ang mga sagot.';
$string['settings:max_total_content'] = 'Pinakamaraming kabuuang nilalaman (mga karakter)';
$string['settings:max_total_content_desc'] = 'Pinakamataas na kabuuang bilang ng karakter ng nilalaman ng kurso na isinasama sa system prompt. Binabawasan ng mas mababang halaga ang laki ng prompt at pinapabilis ang mga sagot.';
$string['settings:spend_guard_heading'] = 'Proteksyon sa gastos at optimizer';
$string['settings:spend_guard_heading_desc'] = 'Magtakda ng hangganan ng gastos sa LLM bawat panahon. Kapag naabot ang hangganan, sinususpinde ng [[tutorshort]] ang mga kahilingan o lumilipat sa mas murang tagapagbigay mula sa inyong failover chain. Tingnan ang <a href="{$a}">pahina ng halaga ng token</a> para sa kasalukuyang katayuan ng gastos at mga rekomendasyon ng optimizer.';
$string['settings:spend_cap_period'] = 'Panahon ng hangganan ng gastos';
$string['settings:spend_cap_period_desc'] = 'Gaano kadalas nire-reset ang hangganan ng gastos. Nakaayon sa kalendaryo: nagsisimula ang buwanan sa ika-1 ng buwan, ang lingguhan tuwing Lunes, at ang araw-araw sa hatinggabi.';
$string['settings:spend_cap_site'] = 'Hangganan ng gastos para sa buong site (USD)';
$string['settings:spend_cap_site_desc'] = 'Pinagsamang hangganan sa USD para sa lahat ng kurso at kakayahan sa kasalukuyang panahon. <code>0</code> = walang hangganan. Nangingibabaw ang mga hangganan ayon sa kakayahan sa ibaba kapag itinakda ang mga ito.';
$string['settings:spend_cap_chat'] = 'Hangganan ng chat (USD)';
$string['settings:spend_cap_chat_desc'] = 'Hangganan para lamang sa chat at pagsusulit ng mga mag-aaral. <code>0</code> = ginagamit ang hangganan ng buong site.';
$string['settings:spend_cap_voice'] = 'Hangganan ng boses (USD)';
$string['settings:spend_cap_voice_desc'] = 'Hangganan para sa boses (Realtime + TTS + STT). Karaniwang ang boses ang pinakamalaking gastos — limitahan ito muna.';
$string['settings:spend_cap_rag'] = 'Hangganan ng RAG (USD)';
$string['settings:spend_cap_rag_desc'] = 'Hangganan para sa mga tawag sa embedding na naganap habang ini-index ang mga kurso.';
$string['settings:spend_cap_analytics'] = 'Hangganan ng analytics (USD)';
$string['settings:spend_cap_analytics_desc'] = 'Hangganan para sa mga query sa Learning Radar ng administrador.';
$string['settings:spend_failover_chain'] = 'Failover chain';
$string['settings:spend_failover_chain_desc'] = 'Kapag naabot ang hangganan, sinusubukan ng [[tutorshort]] ang mga tagapagbigay na ito ayon sa pagkakasunod. Isang entry bawat linya, sa anyong <code>capability:label</code>. Tumutukoy ang mga label sa mga entry sa Mga tagapagbigay para sa paghahambing (para sa <code>chat</code> / <code>analytics</code>) o sa Mga tagapagbigay ng boses (para sa <code>voice</code>). Ang mga linyang nagsisimula sa <code>#</code> ay mga komento. Halimbawa:<br><code>chat:claude-haiku<br>chat:ollama-local<br>voice:openai-prod<br>analytics:deepseek</code>';
$string['settings:failover_per_call_enabled'] = 'Paglipat sa failover bawat tawag (v5.5.0)';
$string['settings:failover_per_call_enabled_desc'] = 'Kapag nakabukas, binabalot ng bawat tawag sa chat ang pangunahing tagapagbigay sa isang decorator ng failover chain. Kung ang isang tawag ay maubusan ng oras o makatanggap ng 5xx na error, lilipat ang [[tutorshort]] sa susunod na entry sa <strong>failover chain</strong> sa itaas at magbubukas ng 15-minutong circuit para sa nabigong tagapagbigay. Bawat paglipat ay nagsusulat ng linya ng pag-audit (<code>failover_fallthrough</code>); pagkatapos buksan, tingnan ang Pangangasiwa -> [[tutorshort]] -> Audit log upang tiyaking gumagana ang chain. Nakasara bilang default; buksan lamang matapos mapatunayan ang chain at makumpirma ng inyong institusyon na mayroong kinakailangang kasunduan sa pagproseso ng datos para sa bawat tagapagbigay sa chain.';
$string['settings:failover_timeout_chat'] = 'Failover: takdang oras ng chat (segundo)';
$string['settings:failover_timeout_chat_desc'] = 'Gaano katagal maghihintay ng unang token mula sa isang tagapagbigay ng chat bago lumipat. Default na 8 segundo. Mas mabilis na lumalayo ang mas mababang halaga sa mabagal na tagapagbigay, kapalit ng mas maraming maling alarma sa pansamantalang mabagal na kahilingan; pinananatili ng mas mataas na halaga ang chain sa pangunahing tagapagbigay nang mas matagal. Isinasaalang-alang lamang kapag nakabukas ang <strong>paglipat sa failover bawat tawag</strong>.';
$string['settings:spend_notify_emails'] = 'Mga tatanggap ng babala sa gastos';
$string['settings:spend_notify_emails_desc'] = 'Mga email address na pinaghihiwalay ng kuwit na aabisuhan sa 80%, 95%, at 100% ng hangganan. Iwanang blangko upang abisuhan ang lahat ng administrador ng site.';
$string['settings:opt_cost_weight'] = 'Optimizer: bigat ng halaga';
$string['settings:opt_cost_weight_desc'] = 'Gaano kalaki ang pagtimbang ng optimizer sa halaga kapag inaayos ang ranggo ng mga tagapagbigay. Binabalewala ng 0.0 ang halaga, samantalang ini-optimize ng 1.0 ayon sa halaga lamang. Tinitimbang kasama ng bigat ng kalidad.';
$string['settings:opt_quality_weight'] = 'Optimizer: bigat ng kalidad';
$string['settings:opt_quality_weight_desc'] = 'Gaano kalaki ang pagtimbang ng optimizer sa kasiyahan ng mag-aaral (bahagdan ng positibong rating) kapag inaayos ang ranggo ng mga tagapagbigay. Binabalewala ng 0.0 ang kalidad.';
$string['settings:inactivity_reminder_enabled'] = 'Mga paalala sa kawalan ng aktibidad';
$string['settings:inactivity_reminder_enabled_desc'] = 'Nagpapadala ng lingguhang email sa mga mag-aaral na hindi nagbukas ng kanilang kurso sa loob ng nakatakdang bilang ng araw.';
$string['settings:inactivity_threshold_days'] = 'Hangganan ng kawalan ng aktibidad (araw)';
$string['settings:inactivity_threshold_days_desc'] = 'Ilang araw na kawalan ng aktibidad bago ipadala ang email na paalala.';
$string['settings:voice_providers_heading'] = 'Mga tagapagbigay ng boses (Realtime, TTS, STT)';
$string['settings:voice_providers_heading_desc'] = 'Mag-configure ng isa o higit pang tagapagbigay ng voice API. Hiwalay ang mga setting na ito sa tagapagbigay ng chat sa itaas at sa tagapagbigay ng embedding para sa RAG — may sariling listahan ng tagapagbigay ang boses dahil sa kasalukuyan ay OpenAI at xAI lamang ang nag-aalok ng mga endpoint na Realtime na nakabatay sa WebSocket, TTS, at STT. Gamitin ang mga dropdown sa ibaba upang piliin kung aling nakarehistrong tagapagbigay ang hahawak sa bawat kakayahan. Kung walang tinukoy na hilera, ilalapat ang lumang asal na iisang susi (ang Realtime API key sa itaas o ang pangunahing susi ng OpenAI). Kailangang mag-configure ng kahit isang hilera dito ang isang site na gumagamit ng Together AI / Anthropic / DeepSeek / Gemini / Mistral para sa chat upang gumana ang boses.';
$string['settings:voice_active_realtime'] = 'Aktibong tagapagbigay ng Realtime';
$string['settings:voice_active_realtime_desc'] = 'Kung aling na-configure na tagapagbigay ng boses ang hahawak sa mga sesyon ng Realtime voice agent.';
$string['settings:voice_active_tts'] = 'Aktibong tagapagbigay ng TTS';
$string['settings:voice_active_tts_desc'] = 'Kung aling na-configure na tagapagbigay ng boses ang magbabasa nang malakas ng mga sagot ng AI.';
$string['settings:voice_active_stt'] = 'Aktibong tagapagbigay ng STT';
$string['settings:voice_active_stt_desc'] = 'Kung aling tagapagbigay ang magsasalin ng pananalita ng mag-aaral sa teksto. Iwanang blangko upang unahin ang sariling-host na Whisper server kung na-configure ito sa ibaba, saka ang unang hilera ng mga tagapagbigay ng boses o ang lumang susi.';
$string['settings:stt_selfhosted_enabled'] = 'Buksan ang sariling-host na transkripsyon';
$string['settings:stt_selfhosted_enabled_desc'] = 'Ginagamit ang sariling-host na Whisper server sa ibaba bilang daan ng pagsasalin ng pananalita sa teksto para sa voice input at Soapbox. Kailangan ng address ng server sa ibaba. Kapag nakasara, babalik ang transkripsyon sa naka-host na daan (OpenAI Whisper) o sa daan ng browser, kahit na nakatakda ang address.';
$string['settings:stt_selfhosted_warm'] = 'Painitin kapag nagsimula ang pagre-record sa Soapbox';
$string['settings:stt_selfhosted_warm_desc'] = 'Kapag nakabukas, ang pagsisimula ng pagre-record sa Soapbox ay nagpapadala ng magaan na kahilingang "pampainit" (hangga\'t maaari) sa sariling-host na server ng transkripsyon, upang ang host na lumiliit hanggang zero (halimbawa ang Cloud Run) ay makapagsimula habang nagre-record pa ang mag-aaral — sa gayon, nananatiling nakatago ang antala ng malamig na pagsisimula mula sa transkripsyong tumatakbo sa pagsusumite. Walang bisa kung hindi nakatakda sa itaas ang address ng sariling-host na server. Nakasara bilang default.';
$string['settings:voice_tab_enabled'] = 'Buksan ang tab na Boses';
$string['settings:voice_tab_enabled_desc'] = 'Ipinapakita ang tab na Boses sa ibabang navigation bar. Kapag nakasara, ang tab na Chat at Mga tala lamang ang nakikita ng mga mag-aaral. Nananatiling naaabot ang mga kakayahan sa boses (pagsasanay sa pag-uusap, pagsasanay sa bigkas) sa pamamagitan ng mga panimula ng usapan kung hiwalay itong nakabukas.';
$string['settings:soapbox_heading'] = 'Soapbox';
$string['settings:soapbox_heading_desc'] = 'Pagsasanay sa pasalitang presentasyon: kung paano isinasalin sa teksto ang mga recording at kung anong rubric ang gagamitin sa pagmamarka. Buksan ang Soapbox sa bawat kurso gamit ang switch na Soapbox sa seksyong Pedagohiya.';
$string['settings:soapbox_max_seconds'] = 'Pinakamahabang recording ng Soapbox (segundo)';
$string['settings:soapbox_max_seconds_desc'] = 'Ganap na pinakamataas na hangganan ng haba ng recording para sa anumang gawain. Maaaring magtakda ang mga guro ng mas maikling saklaw. Default na 720 (12 minuto).';
$string['settings:soapbox_max_recordings'] = 'Pinakamaraming recording ng Soapbox bawat mag-aaral at gawain';
$string['settings:soapbox_max_recordings_desc'] = 'Ganap na pinakamataas na hangganan ng bilang ng recording na maaaring gawin ng isang mag-aaral sa isang gawain, anuman ang setting ng bilang ng pagsubok bawat gawain. Default na 3.';
$string['settings:soapbox_retention_days'] = 'Panahon ng pag-iingat ng recording ng Soapbox (araw)';
$string['settings:soapbox_retention_days_desc'] = 'Gaano katagal iniingatan ang isang recording bago ito awtomatikong burahin; nananatili ang transkripsyon, marka, at feedback. Nililimitahan sa 1–28 araw. Mas maikli, mas mabuti para sa pagpapaliit ng datos. Default na 7.';
$string['settings:soapbox_video_quality'] = 'Kalidad ng video sa Soapbox';
$string['settings:soapbox_video_quality_desc'] = 'Ang resolusyon at bitrate ng recording. Ito ang pangunahing sanhi ng gastos at bandwidth; malinaw pa ring nakikita sa karaniwang kalidad ang isang tagapagsalitang kuha sa katamtamang lapit. Angkop ang mababang kalidad para sa mahihinang koneksyon; ang mataas na kalidad ay kapag mahalaga lamang ang mga detalyeng biswal.';
$string['settings:soapbox_storage_bucket'] = 'Bucket ng imbakan ng Soapbox';
$string['settings:soapbox_storage_bucket_desc'] = 'Ang S3 bucket para sa mga recording. Default: ang pinagsasaluhang archive bucket.';
$string['settings:soapbox_storage_region'] = 'Rehiyon ng imbakan ng Soapbox';
$string['settings:soapbox_storage_region_desc'] = 'Ang rehiyong AWS ng bucket, halimbawa us-east-1.';
$string['settings:soapbox_storage_prefix'] = 'Unlapi ng key ng imbakan ng Soapbox';
$string['settings:soapbox_storage_prefix_desc'] = 'Ang unlapi ng mga key sa loob ng bucket. Iniimbak ang mga recording sa ilalim ng landas na ito upang matukoy ito ng isang panuntunan sa lifecycle.';
$string['settings:soapbox_storage_key'] = 'ID ng access key ng imbakan ng Soapbox';
$string['settings:soapbox_storage_key_desc'] = 'Ang ID ng access key ng isang IAM principal na limitado sa PutObject/GetObject/DeleteObject sa unlaping nasa itaas.';
$string['settings:soapbox_storage_secret'] = 'Lihim na access key ng imbakan ng Soapbox';
$string['settings:soapbox_storage_secret_desc'] = 'Ang lihim na access key na katumbas ng ID ng access key sa itaas.';
$string['settings:survey_heading'] = 'Sarbey ng mag-aaral';
$string['settings:survey_heading_desc'] = 'I-configure ang sarbey ng karanasan ng mag-aaral sa loob ng chat. <a href="{$a}" class="btn btn-sm btn-outline-primary ml-2">I-edit ang mga tanong sa sarbey &rarr;</a>';
$string['settings:survey_enabled'] = 'Buksan ang mga sarbey';
$string['settings:survey_enabled_desc'] = 'Kapag nakabukas, aalukin ang mga mag-aaral na sagutan ang isang sarbey tungkol sa kanilang karanasan sa AI tutor.';
$string['settings:survey_trigger_messages'] = 'Ipakita pagkatapos ng N mensahe';
$string['settings:survey_trigger_messages_desc'] = 'Ipinapakita ang paanyaya sa sarbey matapos magpadala ang mag-aaral ng ganitong bilang ng mensahe sa isang kurso. Itakda sa 0 upang ipakita lamang ito kapag manu-manong pinatakbo.';
$string['settings:survey_frequency'] = 'Dalas ng sarbey bawat gumagamit';
$string['settings:survey_frequency_desc'] = 'Gaano kadalas maaaring anyayahan ang isang mag-aaral na sagutan ang sarbey sa bawat kurso.';
$string['settings:rubric_heading'] = 'Mga rubric sa pagsasanay';
$string['settings:rubric_heading_desc'] = 'I-configure ang mga rubric sa pagmamarka para sa mga sesyon ng pagsasanay sa pag-uusap at bigkas. Sa pagtatapos ng sesyon ng pagsasanay, tumatanggap ang mga mag-aaral ng marka at feedback na binuo ng AI. <a href="{$a}" class="btn btn-sm btn-outline-primary ml-2">I-edit ang mga rubric &rarr;</a>';
$string['settings:practice_scoring_enabled'] = 'Buksan ang pagmamarka ng pagsasanay';
$string['settings:practice_scoring_enabled_desc'] = 'Kapag nakabukas, tumatanggap ang mga mag-aaral pagkatapos ng mga sesyon ng pagsasanay sa pag-uusap at bigkas ng isang score card na may pagtatasa sa bawat pamantayan at may feedback.';
$string['settings:usertesting_heading'] = 'Pagsubok sa kadalian ng paggamit';
$string['settings:usertesting_heading_desc'] = 'Pagsubok sa kadalian ng paggamit sa loob ng widget na may pagtatasang batay sa gawain. Kinukumpleto ng mga mag-aaral ang mga gawain sa katuwang at minamarkahan ang kanilang karanasan. Lumilitaw ang mga resulta sa dashboard ng analytics.';
$string['settings:usertesting_enabled'] = 'Buksan ang pagsubok sa kadalian ng paggamit';
$string['settings:usertesting_enabled_desc'] = 'Ipinapakita ang link na "Pagsubok sa kadalian ng paggamit" sa ilalim ng widget. Kapag nakabukas, maaabot ng mga mag-aaral ang mga gawain sa pagsubok.';
$string['settings:usertesting_external_url'] = 'Address ng panlabas na form (bersyong C)';
$string['settings:usertesting_external_url_desc'] = 'Opsyonal: ang address ng isang panlabas na form (halimbawa Google Forms o Typeform). Gamitin ang mga placeholder: {{userid}}, {{courseid}}, {{messages}}, {{session_minutes}}. Kung nakatakda, bubuksan ng pag-click sa "Pagsubok sa kadalian ng paggamit" ang address na ito na punô na ang konteksto. Iwanang blangko upang gamitin lamang ang panel ng pagsubok sa loob ng widget.';
$string['settings:footer_links_heading'] = 'Mga link sa ibaba';
$string['settings:footer_links_heading_desc'] = 'Iangkop ang mga link na ipinapakita sa ibaba ng katuwang: isang opsyonal na link sa mga alok na kurso sa ilalim ng link ng feedback, gayundin ang pananalita ng link ng feedback at ng panel nito.';
$string['settings:footer_courses_text'] = 'Teksto ng link sa mga kurso';
$string['settings:footer_courses_text_desc'] = 'Ang teksto ng link na ipinapakita sa ilalim ng link ng feedback. Iwanang blangko upang lubusang itago ang link.';
$string['settings:footer_courses_url'] = 'Address ng link sa mga kurso';
$string['settings:footer_courses_url_desc'] = 'Ang patutunguhan ng link sa mga kurso (bumubukas sa bagong tab). Nakatago ang link kung blangko ang field na ito.';
$string['settings:feedback_link_label'] = 'Label ng link ng feedback';
$string['settings:feedback_link_label_desc'] = 'Pinapalitan ang teksto ng link ng feedback sa ibaba, halimbawa "Magpadala ng puna tungkol sa [[tutorshort]] sa pangkat ng IT". Iwanang blangko upang gamitin ang isinaling default na label na "Feedback".';
$string['settings:feedback_panel_intro'] = 'Panimula ng panel ng feedback';
$string['settings:feedback_panel_intro_desc'] = 'Ang linya ng panimulang ipinapakita sa itaas ng panel ng feedback. Nililinaw kung saan napupunta ang mga puna. Iwanang blangko kung ayaw ng linyang panimula.';
$string['settings:quiz_provider'] = 'Tagapagbigay ng katuwang sa pagsusulit';
$string['settings:quiz_provider_desc'] = 'Ang ID ng tagapagbigay (halimbawa <code>claude</code> o <code>openai</code>) para sa paggawa ng pagsusulit. Kailangang tumugma sa isang hilera sa Mga tagapagbigay para sa paghahambing. Iwanang blangko upang gamitin ang tagapagbigay ng chat.';
$string['settings:quiz_model'] = 'Modelo ng katuwang sa pagsusulit';
$string['settings:quiz_model_desc'] = 'Ang pangalan ng modelo para sa paggawa ng pagsusulit, halimbawa <code>claude-haiku-4-5</code>. Kailangang punan ang field na ito at ang tagapagbigay upang mailapat ang pagpapalit.';
$string['settings:branding_heading'] = 'Pagkakakilanlan ng tatak';
$string['settings:branding_heading_desc'] = 'Iangkop ang pangalan at anyo ng katuwang.';
$string['settings:institution_short_name'] = 'Maikling pangalan ng institusyon';
$string['settings:institution_short_name_desc'] = 'Ang pinaikling pangalan ng institusyon para sa masisikip na elemento ng interface (halimbawa "State U").';
$string['settings:display_name'] = 'Ipinapakitang pangalan ng katuwang';
$string['settings:display_name_desc'] = 'Ang buong pangalan ng katuwang na AI, gaya ng lumilitaw sa mga pagbati at sa welcome screen (halimbawa "Online na Katuwang sa Pagkatuto").';
$string['settings:short_name'] = 'Maikling pangalan ng katuwang';
$string['settings:short_name_desc'] = 'Ang maikling pangalang ginagamit sa title bar at sa masisikip na elemento ng interface (halimbawa "Katuwang").';
$string['settings:welcome_message'] = 'Mensahe sa welcome screen';
