$string['privacynotice:lastupdated'] = 'Huling update: {$a}. Bersyon 1.0.';
$string['privacynotice:whatis'] = 'Ano ang [[tutorshort]]';
$string['privacynotice:whatis_p1'] = 'Ang [[tutorshort]] ay ang AI powered na learning coach ng [[uniname]], nakabuo sa loob ng ilang kurso. Kapag available ang [[tutorshort]] sa isang kurso, makikita mo ang chat widget sa mga pahina ng kurso. Maaari mong tanungin ang [[tutorshort]] tungkol sa materyal, humingi ng pampraktis na tanong, magplano ng iskedyul ng pag-aaral, at gumamit ng mga voice feature kung naka-enable ito sa kurso mo.';
$string['privacynotice:whatis_p2'] = 'Hindi available ang [[tutorshort]] sa lahat ng kurso sa [[uniname]]. Ang desisyong i-enable ang [[tutorshort]] sa isang kurso ay ginagawa ng course developer.';
$string['privacynotice:collects'] = 'Anong Impormasyon ang Kinokolekta ng [[tutorshort]]';
$string['privacynotice:collects_p1'] = 'Kapag gumagamit ka ng [[tutorshort]] sa isang kurso, itinatala ng [[uniname]] ang mga mensahe mo, ang mga sagot ng [[tutorshort]], ang kurso at oras ng bawat palitan, ang mga rating at feedback na ibinibigay mo, ang plano sa pag-aaral at mga kagustuhan sa paalala kung gagawa ka ng mga ito, ang napiling avatar mo, at isang maikling buod ng profile na binubuo ng [[tutorshort]] mula sa mga usapan mo para mapersonalize ang mga susunod na session.';
$string['privacynotice:collects_p2'] = 'Kinokolekta rin ng [[tutorshort]] ang karaniwang teknikal na datos na kailangan para mapatakbo ang serbisyo: ang Moodle user id mo, IP address, uri ng browser, at timestamp. Walang sariling tala ang [[tutorshort]] ng buong pangalan mo, email address (maliban kung mag-opt out ka sa mga email, na nag-iimbak ng address na saklaw ng opt-out), address ng tahanan, numero ng telepono (maliban kung magbibigay ka ng isa para sa mga paalala), impormasyon sa pagbabayad, o mga identifier na ibinigay ng gobyerno; kung saan lumalabas ang pangalan mo katabi ng datos ng [[tutorshort]], binasa ito mula sa dati mo nang [[uniname]] account at hindi iniimbak ng [[tutorshort]].';
$string['privacynotice:uses'] = 'Paano Ginagamit ang Impormasyon Mo';
$string['privacynotice:uses_item1'] = 'Sagutin ang mga tanong mo sa sandaling iyon.';
$string['privacynotice:uses_item2'] = 'Ipersonalize ang mga sagot ng [[tutorshort]] para sa iyo.';
$string['privacynotice:uses_item3'] = 'Pagbutihin ang [[tutorshort]] mismo, gamit ang anonymized at pinagsama-samang datos.';
$string['privacynotice:uses_item4'] = 'Matukoy at mapigilan ang pang-aabuso.';
$string['privacynotice:uses_item5'] = 'Bumuo ng analytics na tumutulong sa mga may-akda ng kurso na pagbutihin ang materyal. Ina-anonymize ang analytics bago maabot ang isang taong tagasuri.';
$string['privacynotice:uses_nosell'] = 'Hindi ipinagbibili ng [[uniname]] ang impormasyon mo. Hindi ginagamit ng [[uniname]] ang mga usapan mo sa [[tutorshort]] para i-market sa iyo ang mga produktong walang kaugnayan.';
$string['privacynotice:whosees'] = 'Sino ang Nakakakita ng Impormasyon Mo';
$string['privacynotice:whosees_intro'] = 'Para masagot ang mga tanong mo, nakikipagtulungan ang [[tutorshort]] sa isang AI service (katulad ng ChatGPT o Claude) sa likod ng eksena. Ito ang eksaktong ibinabahagi ng [[tutorshort]] sa serbisyong iyon:';
$string['privacynotice:shared_item1'] = 'Ang unang pangalan mo';
$string['privacynotice:shared_item2'] = 'Isang buod ng materyal ng kursong pinag-aaralan mo';
$string['privacynotice:shared_item3'] = 'Ang huling 10 mensahe mula sa kasalukuyang usapan mo sa [[tutorshort]]';
$string['privacynotice:shared_item4'] = 'Ang plano mo sa pag-aaral, kung may nagawa ka';
$string['privacynotice:shared_item5'] = 'Ang buod ng profile mo, kung may nagawa ka';
$string['privacynotice:whosees_never'] = 'Ito ang hindi kailanman ibinabahagi ng [[tutorshort]]:';
$string['privacynotice:notshared_item1'] = 'Ang apelyido mo';
$string['privacynotice:notshared_item2'] = 'Ang email address mo';
$string['privacynotice:notshared_item3'] = 'Ang Moodle username o ID number mo';
$string['privacynotice:notshared_item4'] = 'Ang address ng tahanan mo';
$string['privacynotice:notshared_item5'] = 'Anumang iba pang impormasyong maaaring makapagtukoy sa iyo nang personal';
$string['privacynotice:whosees_contract'] = 'Ang [[uniname]] ay gumagamit lamang ng mga AI service na maingat naming sinuri at inaprubahan. Bawat isa ay may kontrata sa [[uniname]] na naglilimita sa paggamit nila ng impormasyon mo at nagbabawal sa kanila na gamitin ang mga usapan mo sa [[tutorshort]] para sanayin ang AI nila.';
$string['privacynotice:retention'] = 'Gaano Katagal Iniingatan ng [[tutorshort]] ang Impormasyon Mo';
$string['privacynotice:retention_item1'] = 'Iniimbak ang mga usapan mo hanggang burahin mo ang mga ito o hanggang alisin ito nang awtomatiko ng retention period ng site para sa mga usapan (default na dalawang taon ng kawalan ng aktibidad). Ang huling 10 turn lamang ang ipinapadala sa AI model.';
$string['privacynotice:retention_item2'] = 'Ang mga rating, plano sa pag-aaral, at paalala ay itinatago hanggang alisin mo ang mga ito.';
$string['privacynotice:retention_item3'] = 'Ang anonymized na analytics ay itinatago sa ilalim ng Records Retention Policy ng [[uniname]] at hindi maiuugnay pabalik sa iyo.';
$string['privacynotice:retention_item4'] = 'Ang mga audit at operational log ay itinatago hanggang 365 araw. Itinatala ng mga ito na may mensaheng ipinadala — ang oras, ang kurso, at ang network address na pinanggalingan nito — ngunit hindi kailanman ang nilalaman ng isinulat mo. Ang mga entry na iyon ay may user id mo, hindi ang pangalan mo; kung may pangalang lumalabas sa tingin ng administrador sa log, binasa ito mula sa dati mo nang rekord ng [[uniname]] account.';
$string['privacynotice:retention_deletion'] = 'Kapag binura ang [[uniname]] user account mo, buburahin ang lahat ng datos ng [[tutorshort]] na nakaugnay sa user id mo sa loob ng parehong operasyon.';
$string['privacynotice:rights'] = 'Ang Mga Karapatan Mo';
$string['privacynotice:rights_access'] = 'Pag-access.';
$string['privacynotice:rights_access_desc'] = 'Tingnan ang kasalukuyang usapan mo sa widget; i-download ang kumpletong kopya ng lahat ng datos ng [[tutorshort]] mula sa pahina ng user settings ng [[tutorshort]].';
$string['privacynotice:rights_download'] = 'Pag-download.';
$string['privacynotice:rights_download_desc'] = 'May button na "I-download ang datos ko sa [[tutorshort]]" ang pahina ng user settings na bumubuo ng structured file na may lahat ng datos mo sa [[tutorshort]].';
$string['privacynotice:rights_delete'] = 'Pagbura.';
$string['privacynotice:rights_delete_desc'] = 'Nag-aalok ang parehong pahina ng opsyon sa pagbura sa antas ng kurso at sa kabuuan. Agad ang pagbura.';
$string['privacynotice:rights_correction'] = 'Pagwawasto.';
$string['privacynotice:rights_correction_desc'] = 'Ang mga usapan sa [[tutorshort]] ay hilaw na transcript at karaniwang hindi binabago. Kung may hinalaw na rekord na mukhang mali, magpatuloy sa paggamit ng [[tutorshort]] o kontakin ang [[uniname]] sa address sa ibaba.';
$string['privacynotice:rights_object'] = 'Pagtutol o paglilimita.';
$string['privacynotice:rights_object_desc'] = 'Hindi mo kailangang gumamit ng [[tutorshort]]. Maaari mong alisin ang datos mo anumang oras.';
$string['privacynotice:rights_portability'] = 'Portability.';
$string['privacynotice:rights_portability_desc'] = 'Ang download ay nasa standard na JSON format at maaaring i-import sa ibang sistema.';
$string['privacynotice:rights_complaint'] = 'Reklamo.';
$string['privacynotice:rights_complaint_desc'] = 'Kontakin ang [[uniname]]. Ang mga mag-aaral sa EU, UK, Switzerland, Brazil, o Canada ay maaari ring magreklamo sa kanilang pambansang data protection authority.';
$string['privacynotice:international'] = 'Mga Internasyonal na Mag-aaral';
$string['privacynotice:international_body'] = 'Naglilingkod ang [[uniname]] sa mga mag-aaral sa buong mundo. Kung nasa rehiyon ka na may tiyak na tuntunin sa proteksyon ng datos (GDPR, UK GDPR, LGPD, PIPEDA, Swiss FADP, CCPA), naaangkop ang mga tuntuning iyon sa datos mo sa [[tutorshort]]. Ang legal na basehan ng pagproseso ay ang pagtupad sa kontrata sa edukasyon na mayroon ka sa [[uniname]], kasama ang lehitimong interes ng [[uniname]] na pagbutihin ang mga serbisyong pang-edukasyon nito.';
$string['privacynotice:security'] = 'Seguridad';
$string['privacynotice:security_intro'] = 'Nakatira ang [[tutorshort]] sa loob ng Moodle platform ng [[uniname]], kaya kailangan mong naka-log in para magamit ito. Ilang tiyak na bagay na ginagawa namin para maingatan ang impormasyon mo:';
$string['privacynotice:security_transit'] = 'Habang inililipat:';
$string['privacynotice:security_transit_desc'] = 'Kapag naglalakbay ang mga mensahe mo sa pagitan ng device mo at ng [[tutorshort]], naka-encrypt ang mga ito. Ibig sabihin, kung susubukan ng sinuman na harangin ang mga ito, code na hindi mabasa lang ang makikita nila.';
$string['privacynotice:security_rest'] = 'Habang nakaimbak:';
