$string['settings:bench_default_samples'] = 'Mga prompt kada run';
$string['settings:bench_default_samples_desc'] = 'Kung ilang prompt ang ipinapadala ng isang benchmark na naka-queue mula sa web. Bawat prompt ay nagkakahalaga ng dalawang live na model call — ang sagot at ang judge — kaya ito ang dial ng gastos. Naka-cap sa 50 sa code, na siya ring laki ng golden set at ang nagpapanatili sa isang run sa loob ng rate limit ng provider.';
$string['settings:bench_heading'] = 'Mga benchmark ng modelo';
$string['settings:bench_heading_desc'] = 'Ang isang benchmark run ay sumasagot sa 50 prompt at pinapa-score ang bawat sagot ng isang judge model laban sa isang rubric, pagkatapos ay nag-iimbak ng isang row: rubric mean, gastos kada call, at oras hanggang unang byte. Ang mga run ay naka-queue mula sa pahina ng model registry at isinasagawa ng cron.';
$string['settings:bench_judge_model'] = 'Judge model';
$string['settings:bench_judge_model_desc'] = 'Modelong nagbibigay ng score sa mga sagot. Ang pagpapalit nito ay nagpapalit sa kahulugan ng bawat score na kinuha pagkatapos, kaya naitatala ng bawat run ang judge na ginamit nito at ang release ng plugin na pinatakbo nito.';
$string['settings:bench_judge_provider'] = 'Judge provider';
$string['settings:bench_judge_provider_desc'] = 'Provider para sa modelong nagbibigay ng score sa mga sagot. Ilayo ito sa pool ng mga kalahok: hindi dapat gradohan ng isang modelo ang sarili nito.';
$string['settings:bench_min_quality_n'] = 'Comparability floor (mga na-score na item)';
$string['settings:bench_min_quality_n_desc'] = 'Ang pinakakaunting na-score na item na maaaring taglayin ng isang naitalang run at maihahambing pa rin sa ibang run. Ang mga run sa ilalim ng floor ay itinatago at ipinapakita, may label na sanggunian lamang, kaya hindi kailanman malalampasan ng isang tatlong-prompt na smoke run ang resulta ng limampung prompt. Iwanang 0 para gamitin ang built-in na default; ang floor na 0 ay pupurol sa guard.';
$string['settings:embed_input_type_asymmetric'] = 'Asymmetric query/dokumento (inirerekomenda)';
$string['settings:embed_input_type_mode'] = 'Embedding input type';
$string['settings:embed_input_type_mode_desc'] = 'Para sa mga embedding ng Voyage lamang. Iba ang pag-proyekto ng Voyage sa teksto depende kung ito ay query o dokumento. Ang "Asymmetric" ay nagpapadala ng input_type=query kapag kumukuha at input_type=document kapag nag-iindeks. Ito ang layunin ng vendor at ito ang pinakamahusay na sinusukat sa korpus na ito: ang paggamit ng document projection sa panig ng query ay nagkahalaga ng 30.8 porsyentong puntos ng recall at natalo sa bawat saklaw ng haba ng query (2026-08-21, voyage-3.5, set na hugis-produksyon). Ang "Shared space" ay nagpapadala ng input_type=document sa magkabilang panig; masusukat na mas mahina itong kumuha at umiiral lamang bilang seguro sa paglipat, dahil ang iisang proyeksyon ay nagpapahintulot na palitan ang modelo ng query nang hindi muling ini-embed ang korpus. Piliin ang asymmetric maliban kung ikaw ay nasa gitna ng isang paglipat. Ang pagbabagong ito ay hindi nangangailangan ng muling pag-iindeks: ang proyeksyon lamang sa panig ng query ang nagbabago. HINDI ito ang asymmetric na pagpapares ng modelo (pag-iindeks gamit ang mas malaking modelong Voyage kaysa sa ginagamit mo sa pagtatanong) — ibang teknik iyon na dalawang beses nang hindi na-reproduce sa korpus na ito, at kontrolado ito ng setting ng modelo ng query, hindi ng setting na ito.';
$string['settings:embed_input_type_shared'] = 'Shared space (seguro sa paglipat; mas mahinang kumuha)';
$string['settings:embed_migration_heading'] = 'Migrasyon ng embedding model';
$string['settings:embed_migration_heading_desc'] = 'Ang pagpapalit ng embedding model o ng lapad nito ay nagpapawalang-bisa sa bawat naka-imbak na vector: tinatanggihan ng retriever na i-score ang isang query laban sa mga chunk mula sa ibang embedding space, kaya walang nakukuha ang isang kurso sa halip na makakuha nang hindi maayos. Inilalarawan ng mga setting na ito ang modelong PINAGPAPALITAN mo. Pagkatapos, muling ie-embed ang mga kurso nang isa-isa mula sa pahina ng RAG index, na isinusulat ang mga bagong vector kasabay ng mga luma, at patuloy na maghahain ng retrieval ang live na settings sa itaas hangga\'t hindi mo mismo binabago ito.';
$string['settings:embed_migration_provider_inherit'] = 'Gamitin ang provider na naka-configure sa itaas';
$string['settings:embed_migration_target_apikey'] = 'API key ng target na provider';
$string['settings:embed_migration_target_apikey_desc'] = 'Kailangan lamang kapag iba ang target na provider sa naka-configure sa itaas. Ang walang laman ay nangangahulugang gamitin ang umiiral na embedding key.';
$string['settings:embed_migration_target_dimensions'] = 'Target na lapad ng embedding';
$string['settings:embed_migration_target_dimensions_desc'] = 'Lapad ng vector na hihilingin sa panahon ng migrasyon. Ang 0 ay ang native na lapad ng modelo. Tinatanggap ng Voyage ang 256, 512, 1024 at 2048; ang lapad na hindi inaalok ng modelo ay tinatanggal sa request kaysa ipadala, na tahimik na magbibigay sa iyo ng native na lapad sa halip na ang hiniling mo.';
$string['settings:embed_migration_target_model'] = 'Target na embedding model';
$string['settings:embed_migration_target_model_desc'] = 'Pangalan ng modelong gagamitin sa pag-embed sa panahon ng migrasyon, halimbawa <code>voyage-4-large</code>. Ang walang laman ay nangangahulugang walang naka-configure na migrasyon at wala ring iaalok ang pahina ng RAG index.';
$string['settings:embed_migration_target_provider'] = 'Target na embedding provider';
$string['settings:embed_migration_target_provider_desc'] = 'Iwanang walang laman para mag-migrate sa loob ng provider na naka-configure na sa itaas.';
$string['settings:rerank_min_query_chars'] = 'Rerank: minimum na haba ng query';
$string['settings:rerank_min_query_chars_desc'] = 'Laktawan ang re-ranker para sa mga query na ganito kahaba ang mga karakter o mas maikli pa. Ang mga maikling query ay hugis-keyword at halos wala nang naidadagdag ang re-ranker sa cosine similarity sa dalawa o tatlong salita. Sinukat sa RAG fixture set: ang pag-gate sa 50 ay nakakuha ng 67.7% recall kumpara sa 67.2% para sa laging bukas, sa halos isang-katlo ng gastos. Itakda sa 0 para i-rerank ang bawat query. Ang mga nilaktawang re-rank ay naitatala sa message log bilang "[Rerank skipped: short_query]" para makumpirma mo na gumagana ang gate.';
$string['settings:spend_export_key'] = 'Spend export key';
$string['settings:spend_export_key_desc'] = 'Bearer key para sa buwanang endpoint ng AI-spend export sa <code>/local/ai_course_assistant/spend_export.php</code>, na hinihila ng spend dashboard isang beses sa isang buwan. Iwanang walang laman para i-off ang endpoint — magsasauli na ito ng 404 sa bawat request. Ang key ay tinatanggap LAMANG sa isang <code>Authorization: Bearer</code> header, hindi kailanman sa URL. Bumuo ng mahabang random na halaga; kahit sino na may hawak nito ay makakabasa ng AI spend ng buong site. Ang bawat matagumpay na export ay naitatala sa audit log ng plugin.';
$string['task:migrate_course_embeddings'] = 'I-migrate ang isang kurso sa bagong embedding model';
$string['task:model_price_drift_check'] = 'Pagtingin sa price drift ng modelo';
$string['task:run_model_benchmark'] = 'I-benchmark ang isang modelo';

