$string['privacy:metadata:bench'] = 'Mga benchmark run ng provider: ang mga resulta ng paghahambing ng modelo na binuo ng isang administrador ng site. Ang tanging personal na datos ay ang identifier ng administrador na nagsimula ng run. Ang mga row na ito ay configuration ng site at hindi personal na datos tungkol sa isang mag-aaral, kaya hindi kasama ang mga ito sa pag-export ng datos at hindi tinatanggal kapag humiling ng pagbura ang isang gumagamit.';
$string['privacy:metadata:bench:createdby'] = 'Ang administrador ng site na nagsimula ng benchmark run na ito. Blangko kapag sinimulan ang run mula sa command line.';
$string['privacy:metadata:models'] = 'Mga entry sa model registry: ang mga per-model na override sa presyo at kakayahan na inaalagaan ng isang administrador ng site. Ang tanging personal na datos ay ang identifier ng administrador na huling nag-save ng entry. Ang mga row na ito ay configuration ng site at hindi personal na datos tungkol sa isang mag-aaral, kaya hindi kasama ang mga ito sa pag-export ng datos at hindi tinatanggal kapag humiling ng pagbura ang isang gumagamit.';
$string['privacy:metadata:models:addedby'] = 'Ang administrador ng site na huling nag-save ng entry na ito sa model registry. Blangko kapag isinulat ang entry ng isang awtomatikong price feed.';
$string['privacy:metadata:pricesrc'] = 'Mga kahulugan ng pricing feed: ang mga listahan ng presyo ng vendor na kinukuha ng plugin ayon sa configuration ng isang administrador ng site. Ang tanging personal na datos ay ang identifier ng administrador na nagdagdag ng feed. Ang mga row na ito ay configuration ng site at hindi personal na datos tungkol sa isang mag-aaral, kaya hindi kasama ang mga ito sa pag-export ng datos at hindi tinatanggal kapag humiling ng pagbura ang isang gumagamit.';
$string['privacy:metadata:pricesrc:addedby'] = 'Ang administrador ng site na nagdagdag ng pricing feed na ito. Blangko kapag kasama na ang feed sa plugin.';
$string['privacy:metadata:sbx_assign'] = 'Mga assignment ng presentasyon sa Soapbox: ang mga gawaing itinatakda ng isang guro para sa isang kurso. Ang tanging personal na datos ay ang identifier ng kawani na huling nag-edit ng assignment. Ang mga row na ito ay configuration ng kurso at hindi personal na datos tungkol sa isang mag-aaral, kaya hindi kasama ang mga ito sa pag-export ng datos at hindi tinatanggal kapag humiling ng pagbura ang isang gumagamit, na kung hindi ay babaguhin ang anyo ng isang assignment na pinagtatrabahuhan pa ng ibang mga mag-aaral.';
